  FT["PH-H9212"] = {"id":"PH-H9212","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10763_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Carmona市","en":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the Municipality of Carmona, Province of Cavite and Appropriating Funds Therefor","orig":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the Municipality of Carmona, Province of Cavite and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10763","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10763_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9212-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A Land Transportation Office (LTO) Regular District Office in the Municipality of Carmona, Province of Cavite is hereby established."}},{"id":"PH-H9212-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount needed for the operationalization of the LTO Regular District Office in the Municipality of Carmona, Province of Cavite shall be included in the annual General Appropriations Act."}},{"id":"PH-H9212-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9213"] = {"id":"PH-H9213","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10764_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Malita市","en":"An Act Establishing a Regular District Office of the Land Transportation Office in the Municipality of Malita, Province of Davao Occidental and Appropriating Funds Therefor","orig":"An Act Establishing a Regular District Office of the Land Transportation Office in the Municipality of Malita, Province of Davao Occidental and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10764","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10764_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9213-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a regular district office of the Land Transportation Office (LTO) in the Municipality of Malita, Province of Davao Occidental to be known as the Malita Land Transportation District Office which shall exercise jurisdiction over all municipalities of the province."}},{"id":"PH-H9213-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation and Communications shall immediately include in the Department’s programs the operationalization of the LTO District Office in the Municipality of Malita, Province of Davao Occidental, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9213-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days following its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9214"] = {"id":"PH-H9214","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10765_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Tigaon市","en":"An Act Converting the Goa, Camarines Sur Extension Office of the Land Transportation Office (LTO) Into a Regular LTO District Office to Be Located in the Municipality of Tigaon, Province of Camarines Sur","orig":"An Act Converting the Goa, Camarines Sur Extension Office of the Land Transportation Office (LTO) Into a Regular LTO District Office to Be Located in the Municipality of Tigaon, Province of Camarines Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10765","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10765_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9214-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Goa, Camarines Sur Extension Office of the Land Transportation Office (LTO) is hereby converted into a regular LTO district office to be located in the Municipality of Tigaon, Province of Camarines Sur."}},{"id":"PH-H9214-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation and Communications shall include in the Department’s programs the operationalization of the LTO Regular District Office in the Municipality of Tigaon, Province of Camarines Sur, the initial funding of which shall be charged against the current year’s appropriation of the Goa, Camarines Sur LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H9214-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9215"] = {"id":"PH-H9215","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10766_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"延长人权受害者索赔委员会的存续期间，为此修订第10368号共和国法（题为“规定对马科斯政权期间人权侵犯受害者给予赔偿与承认、记录上述侵犯行为、为此拨款并为其他目的”）第29条","en":"An Act Extending the Life of the Human Rights Victims Claims Board, Amending for This Purpose Section 29 of Republic Act No. 10368 Entitled, “An Act Providing for Reparation and Recognition of Victims of Human Rights Violations During the Marcos Regime, Documentation of Said Violations, Appropriating Funds Therefor and for Other Purposes”","orig":"An Act Extending the Life of the Human Rights Victims Claims Board, Amending for This Purpose Section 29 of Republic Act No. 10368 Entitled, “An Act Providing for Reparation and Recognition of Victims of Human Rights Violations During the Marcos Regime, Documentation of Said Violations, Appropriating Funds Therefor and for Other Purposes”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10766","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10766_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9215-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 29 of Republic Act No. 10368 is hereby amended to read as follows:\n“SEC. 29. Work Period; Sunset Clause. – The Board shall complete its work within four (4) years from May 12, 2014. After such period, it shall become functus officio.”"}},{"id":"PH-H9215-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Repealing Clause. – All laws, presidents decrees, executive orders, resolutions, rules or regulations, or any part thereof which are inconsistent with any of the provisions of this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H9215-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Effectivity. – This Act shall take effect upon its complete publication in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending the Life of the Human Rights Victims Claims Board, Amending for This Purpose Section 29 of Republic Act No. 10368 Entitled, “An Act Providing for Reparation and Recognition of Victims of Human Rights Violations During the Marcos Regime, Documentation of Said Violations, Appropriating Funds Therefor and for Other Purposes”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9216"] = {"id":"PH-H9216","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10767_2016.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"制定消除结核病作为公共卫生问题的菲律宾综合行动计划并为此拨款的法案","en":"An Act Establishing a Comprehensive Philippine Plan of Action to Eliminate Tuberculosis as a Public Health Problem and Appropriating Fund Therefor","orig":"An Act Establishing a Comprehensive Philippine Plan of Action to Eliminate Tuberculosis as a Public Health Problem and Appropriating Fund Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 10767","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-26","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10767_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9216-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title – This Act shall be known as the “Comprehensive Tuberculosis Elimination Plan Act”."}},{"id":"PH-H9216-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – The State is mandated to adopt an integrated and comprehensive approach to health development. Towards this end, the State shall support and expand efforts to eliminate tuberculosis as a public health problem by increasing investments for its prevention, treatment and control, and adopting a multisectoral approach in responding to the disease."}},{"id":"PH-H9216-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. – As used in this Act:\n(a) Comprehensive Philippine Plan of Action to Eliminate Tuberculosis refers to the program of the national government for the elimination of tuberculosis in the country; and\n(b) Tuberculosis or TB refers to an infectious but curable disease caused by bacteria called Mycobacterium tuberculosis. It is transmitted from a TB patient to another through coughing, sneezing and spitting and while the bacterium usually affects the lungs, it may also affect the bone and other organs like the kidney and the liver."}},{"id":"PH-H9216-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Comprehensive Philippine Plan of Action to Eliminate Tuberculosis. – The Secretary of the Department of Health (DOH) shall establish a Comprehensive Philippine Plan of Action to Eliminate Tuberculosis in consultation with appropriate public and private entities. The Philippine Plan of Action shall consist of the following:\n(a) The country’s targets and strategies in addressing the disease;\n(b) The prevention, diagnosis, treatment, care and support, and other components of the country’s response;\n(c) The development and application of appropriate technologies to diagnose and treat the disease;\n(d) The strengthening of linkages with local and international organizations for possible partnership in education, advocacy, research and funding assistance;\n(e) The establishment of a review and monitoring system to gather data and monitor the progress made in the elimination of tuberculosis; and\n(f) The immediate mobilization of anti-TB services during and after natural and man-made disasters through collaborative efforts of national and local governments and other entities."}},{"id":"PH-H9216-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Strengthening of the National and Regional Coordinating Committees. – The National Coordinating Committee (NCC) and the Regional Coordinating Committee (RCC) of the DOH shall serve as the National TB Control Program’s (NTP’s) arm in strengthening and supporting nationwide capacity for program operations and bridging collaborative efforts between the public and private sector.\nThe Secretary of Health shall continue to improve the capability of the existing NCC and RCC in ensuring efficiency in the implementation, monitoring and evaluation of the Philippine Plan of Action and in the coordination of efforts of various sectors."}},{"id":"PH-H9216-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Research, Demonstration Projects, Education and Training. – The Secretary of Health shall, directly or through grants to public or nonprofit private entities, perform the following activities:\n(a) Conduct basic and clinical research based on the health agenda to be developed by partners in the academe, health professional groups and other local health partners with possible support from foreign organizations;\n(b) Develop demonstration projects to generate evidence for responsive policies and to develop regional capabilities for the prevention, detection, control, and elimination of tuberculosis;\n(c) Conduct nationwide public information campaign and education programs;\n(d) Undertake education, training and clinical skills improvement activities for health care providers;\n(e) Provide support for model centers to sustain their initiatives under subparagraphs (b), (c) and (d); and\n(f) Collaborate with local and foreign organizations for partnership in various activities and in providing technical and funding support."}},{"id":"PH-H9216-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Strengthening of the Regional Centers for Health Development in the Provision of Health Services to Eliminate TB. – The Secretary of Health shall strengthen the Regional Centers for Health Development in the provision of health services to eliminate TB by undertaking the following activities:\n(a) Provide free laboratory services through the DOH retained hospitals;\n(b) Provide reliable supply of drugs to patients for free by ensuring that local health centers, through coordination with local government units (LGUs) concerned, have sufficient supply of medicines for the communities they serve;\n(c) Undertake public information and education programs to train the public on basic ways and means to prevent the spread of tuberculosis;\n(d) Train and enhance the capability of health providers in both public and private hospitals;\n(e) Ensure the proper monitoring of tuberculosis cases in the country; and\n(f) Ensure that monitoring services are extended as far as practicable, at the lowest local level health unit."}},{"id":"PH-H9216-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Education Programs. – The Secretary of Health, in coordination with the Commission on Higher Education (CHED), shall encourage the faculty of schools of medicine, nursing or medical technology and allied health institutions, to intensify information and education programs, including the development of curricula, to significantly increase the opportunities for students and for practicing providers to learn the principles and practices of preventing, detecting, managing, and controlling tuberculosis."}},{"id":"PH-H9216-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Inclusion in Basic Education. – The Secretary of Health, in coordination with the Secretary of the Department of Education (DepED), shall work for the inclusion of modules on the principles and practices of preventing, detecting, managing and controlling tuberculosis in the health curriculum of every public and private elementary and high school."}},{"id":"PH-H9216-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Media Campaign. – The Secretary of Health, in coordination with the Philippine Information Agency (PIA), shall encourage local media outlets to launch a media campaign on tuberculosis control, treatment and management, using all forms of multimedia and other electronic means of communication.\nThe media campaign shall include materials that would discourage the general public from spitting in public places and exhibiting unhygienic behavior that tend to undermine the overall effort of preventing the spread of the disease."}},{"id":"PH-H9216-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Regulation on Sale and Use of TB Drugs. – The Food and Drug Administration (FDA) shall strengthen its implementation of the “No prescription, No anti-TB drugs” to regulate the sale and use of anti-TB drugs in the market. It shall also ensure the quality of TB drugs distributed in the market."}},{"id":"PH-H9216-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Notification on TB Cases. – All public and private health centers, hospitals and facilities shall observe the national protocol on TB management arid shall notify the DOH of all TB cases as prescribed under the Manual of Procedures of the National TB Program and the Philippine Plan of Action on Tuberculosis Control."}},{"id":"PH-H9216-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"PhilHealth TB Package. – The Philippine Health Insurance Corporation, otherwise known as the PhilHealth, shall, as far as practicable, expand its benefit package for TB patients to include new, relapse and return-after-default cases, and extension of treatment.\nThe PhilHealth shall enhance its present outpatient Directly Observed Treatment Short Course (DOTS) package to make it more responsive to patients’ needs. It shall likewise increase the number of accredited DOTS facilities to widen target beneficiaries who may avail of reimbursements."}},{"id":"PH-H9216-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Report. – The Secretary of Health shall submit an annual report to the Committees on Health of the Senate and the House of Representatives on the activities carried out to comply with the provisions of this Act."}},{"id":"PH-H9216-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Appropriations. – The amount necessary to implement the provisions of this Act shall be charged against the appropriations of the DOH, the DepED, the CHED and the PIA under the General Appropriations Act."}},{"id":"PH-H9216-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Implementing Rules and Regulations. – The DOH, in consultation with the DepED, the CHED, the PIA, the LGUs, nongovernment organizations and other concerned entities, shall issue the rules and regulations implementing the provisions of this Act within ninety (90) days from its effectivity."}},{"id":"PH-H9216-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause. – If any provision or part hereof is held invalid or declared unconstitutional, the other provisions which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H9216-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Repealing Clause. – Any law, presidential decree or issuance, executive order, letter of instruction, administrative order, rule or regulation contrary to or inconsistent with the provisions of this Act is hereby repealed, modified or amended accordingly."}},{"id":"PH-H9216-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Comprehensive Philippine Plan of Action to Eliminate Tuberculosis as a Public Health Problem and Appropriating Fund Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9217"] = {"id":"PH-H9217","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10768_2016.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Iligan市","en":"Iligan City Charter Day","orig":"An Act Declaring August 11 of Every Year a Special Working Holiday in the City of Iligan, Province of Isabela in Commemoration of Its Charter Day Anniversary to Be Known as “Iligan City Charter Day”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10768","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-26","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10768_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9217-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"August 11 of every year is declared a special working holiday in the City of Ilagan, Province of Isabela in commemoration of its Charter Day Anniversary to be known as “Ilagan City Charter Day”. When the holiday fells on a Saturday or a Sunday, the special working day shall be observed on the Monday that follows."}},{"id":"PH-H9217-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9218"] = {"id":"PH-H9218","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10769_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Sta市","en":"An Act Converting the Extension Office of the Land Transportation Office (LTO) Located in the Municipality of Sta. Maria, Province of Bulacan Into a Regular LTO District Office and Appropriating Funds Therefor","orig":"An Act Converting the Extension Office of the Land Transportation Office (LTO) Located in the Municipality of Sta. Maria, Province of Bulacan Into a Regular LTO District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10769","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-26","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10769_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9218-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office (LTO) Extension Office located in the Municipality of Sta. Maria, Province of Bulacan is hereby converted into a regular LTO district office."}},{"id":"PH-H9218-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department’s programs the operationalization of the Regular LTO District Office in the Municipality of Sta. Maria, Province of Bulacan, the initial funding of which shall be charged against the current year’s appropriations of the Sta. Maria LTO Extension Office. Thereafter, such sums as may be necessary for the continued operation of the Regular LTO District Office shall be included in the annual General Appropriations Act."}},{"id":"PH-H9218-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, rules and regulations inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H9218-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days following the completion of its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9219"] = {"id":"PH-H9219","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10770_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将宿务市Vicente Sotto纪念医疗中心床位由八百（800）张增至一千二百（1,200）张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of Vicente Sotto Memorial Medical Center, Located in Cebu City, From Eight Hundred (800) to One Thousand Two Hundred (1,200) Bed Capacity, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of Vicente Sotto Memorial Medical Center, Located in Cebu City, From Eight Hundred (800) to One Thousand Two Hundred (1,200) Bed Capacity, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 10770","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-26","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10770_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9219-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of Vicente Sotto Memorial Medical Center is hereby increased from eight hundred (800) to one thousand two hundred (1,200) beds."}},{"id":"PH-H9219-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H9219-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Health is directed to implement this Act."}},{"id":"PH-H9219-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) national newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of Vicente Sotto Memorial Medical Center, Located in Cebu City, From Eight Hundred (800) to One Thousand Two Hundred (1,200) Bed Capacity, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9220"] = {"id":"PH-H9220","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10771_2016.html","fetchedAt":"2026-10-06","articleCount":1,"structureMode":"ARTICLE","title":{"zh":"促进绿色就业创造、给予激励并为此拨款的法案","en":"An Act Promoting the Creation of Green Jobs, Granting Incentives and Appropriating Funds Therefor","orig":"An Act Promoting the Creation of Green Jobs, Granting Incentives and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10771","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-04-29","completenessNote":"全文，共 1 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10771_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9220-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the “Philippine Green Jobs Act of 2016”.\nSECTION 2. Declaration of Policy. – It is the declared policy of the State to:\n(a) Affirm labor as a primary social economic force in promoting sustainable development;\n(b) Afford full protection to labor, local and overseas, organized and unorganized, and promote full and productive employment and equality of employment opportunities for all; and\n(c) Promote the rights of the people to a balanced and healthful ecology in accord with the rhythm and harmony of nature.\nThe State shall identify needed skills, develop training programs, and train and certify workers for jobs in a range of industries that produce goods and render services for the benefit of the environment, conserve natural resources for the future generation, and ensure the sustainable development of the country and its transition into a green economy. In recognition of the participation of individuals and business enterprises in jobs creation, the State shall provide incentives therefor.\nSECTION 3. Coverage. – This Act shall apply to all business enterprises unless otherwise provided herein.\nSECTION 4. Definition of Terms. – As used in this Act:\n(a) Business enterprises refer to establishments engaged in the production, manufacturing, processing, repacking, assembly, or sale of goods and/or services, including service-oriented enterprises. It shall include self-employed or own-account workers, micro, small, and medium enterprises (MSMEs) and community-based business enterprises;\n(b) Climate change refers to a change in climate that can be identified by changes in the mean or variability of its properties and that persists for an extended period typically decades or longer, whether due to natural variability or as a result of human activity;\n(c) Green jobs refer to employment that contributes to preserving or restoring the quality of the environment, be it in the agriculture, industry or services sector. Specifically, but not exclusively, this include jobs that help to protect ecosystems and biodiversity, reduce energy, materials and water consumption through high efficiency strategies, decarbonize the economy, and minimize or altogether avoid generation of all forms of waste and pollution. Green jobs are decent jobs that are productive, respect the rights of workers, deliver a fair income, provide security in the workplace and social protection for families, and promote social dialogue.\n(d) Green economy refers to one which is low-carbon and resource-efficient, and results in the generation of green jobs and in improved human well-being and social equity, while significantly reducing environmental risks and ecological scarcities;\n(e) Green goods and services refer to goods and services that benefit the environment or conserve natural resources, and may include research and development, installation and maintenance services;\n(f) Green technologies refer to the development and application of products, equipment and systems used to conserve the environment and natural resources; and\n(g) Sustainable development refers to development that meets the needs of the present generation without compromising the ability of the future generations to meet their own needs.\nSECTION 5. Incentives. – For the purpose of encouraging business enterprises to generate and sustain green jobs as certified by the Climate Change Commission, as provided in Section 6(o) hereof, business enterprises shall enjoy the following incentives:\n(a) Special deduction from the taxable income equivalent to fifty percent (50%) of the total expenses for skills training and research development expenses which is over and above the allowable ordinary and necessary business deductions for said expenses under the National Internal Revenue Code of 1997, as amended; and\n(b) Tax and duty free importation of capital equipment: Provided, That the capital equipment is actually, directly and exclusively used in the promotion of green jobs of the business enterprise.\nIncentives that will be granted under this Act shall be in addition to fiscal and non-fiscal incentives already granted or provided under existing laws, orders, issuances and regulations. Nothing in this Act shall be interpreted or construed to diminish or limit, in whatever manner, the incentives granted or provided under existing laws, orders, issuances and regulations which shall include, but not limited to, Republic Act No. 10121 or the “Philippine Disaster Risk Reduction and Management Act of 2010”; Republic Act No. 10068 or the “Organic Agriculture Act of 2010”; Republic Act No. 9513 or the “Renewable Energy Act of 2008”; Republic Act No. 9367 or the “Biofuels Act of 2006”; Republic Act No. 9275 or the “Philippine Clean Water Act of 2004”; Republic Act No. 9003 or the “Ecological Solid Waste Management Act of 2000”; Republic Act No. 8749 or the “Philippine Clean Air Act of 1999”; and Republic Act No. 8550 or the “Philippine Fisheries Code of 1998”.\nSECTION 6. Role of Agencies. –\n(a) The Department of Labor and Employment (DOLE) shall, in coordination with other government agencies, formulate a National Green Jobs Human Resource Development Plan on the development, enhancement and utilization of the labor force, both in the private and public sectors. The plan shall have the primary objective of enabling and sustaining the transition into a green economy and the generation of green jobs towards more employment and equal opportunities and the promotion of social justice and workers’ welfare. It shall include programs, projects, and activities pertaining to basic, higher and technical-vocational education and training, database that identifies and links green job opportunities with private and public entities, and information on knowledge and skill requirements of a green economy.\nThe DOLE, in coordination with the Philippine Statistics Authority (PSA), shall also maintain a database of green careers, professions and skills, as well as a list of emerging business enterprises, which generate and sustain green jobs. It shall facilitate skills training assessment and certification, career advocacy, provide productivity and livelihood training, and extend technical assistance to enterprises to ensure labor law compliance.\n(b) The Department of Finance (DOF) shall administer the grant of incentives as discussed in Section 5 of this Act to qualified individuals and business enterprises engaged in registered strategic activities, and shall maintain a database on the same.\n(c) The Department of Environment and Natural Resources (DENR) shall establish and maintain a climate change information management system and network as reference in the formulation of strategies and approaches to develop potential green jobs.\n(d) The Department of Education (DepED) shall implement faculty, facility and curriculum development for primary and secondary education in support of the knowledge and skills requirement of a green economy.\n(e) The Commission on Higher Education (CHED) shall develop and implement curriculum and related standards and instructional materials in support of the green economy.\n(f) The Technical Education and Skills Development Authority (TESDA) shall formulate the necessary training regulations for the implementation of skills training, program registration and assessment and certification in support of the requirements for skilled manpower of the green economy.\n(g) The National Economic and Development Authority (NEDA) shall ensure the mainstreaming of green jobs concern in development plans.\n(h) The Department of Trade and Industry (DTI) shall develop a special business facilitation program for individuals and business enterprises that create green jobs.\n(i) The Professional Regulation Commission (PRC) shall encourage the development of qualifications framework that can facilitate the recognition of knowledge, skills, and competencies of professionals working in the green economy.\n(j) The Department of Science and Technology (DOST) shall, together with the TESDA, assist the DOLE in analyzing skills, training and re-training needs in relation to the use of green technology that has the potential to create new green occupations and greener jobs, especially in industries or sectors undergoing structural changes due to climate change and greening of the economy. It shall also provide a range of business development support to MSMEs. These may include prototyping or modeling of technologies, conducting assessment to match technological needs and demands, subcontracting business to develop clean technologies, providing technical written guides, procedures as well as instructions and training on clean technology for business.\n(k) The Department of Transportation and Communications (DOTC) shall ensure the mainstreaming of green jobs concern in its sectoral development plan and encourage more investments in public transport infrastructure and services to optimize the potential of public transport to foster green growth and job creation. It shall also explore strategies of shifting to more environmentally friendly modes of transport and improving the efficiency of all modes of transportation.\n(l) The Department of Tourism (DOT) shall outline sustainable tourism planning and integrated approach for the promotion of job rich sustainable tourism industry.\n(m) The Department of Public Works and Highways (DPWH) shall develop and implement programs that promote the importance of green building practices in safeguarding the environment and its role in sustainable economic development.\n(n) Any provision in their respective charters to the contrary notwithstanding, government financial institutions (GFIs) shall, in consultation with the Bangko Sentral ng Pilipinas (BSP), provide preferential financial packages to business enterprises that create green jobs.\n(o) The Climate Change Commission (CCC), in consultation with concerned agencies, such as the DENR, the DTI, the DOLE, the Department of Agriculture (DA), the Department of Energy. (DOE), the Department of the Interior and Local Government (DILG), and the DOST, shall develop and administer appropriate standards for the assessment and certification of green goods and services, and green technologies and practices for the purpose of regulating the availment of incentives and ensuring green jobs content pursuant to the National Green Jobs Human Resource Development Plan as provided in Section 6(a) hereof.\nSECTION 7. Role of the Secretary of Labor and Employment. – The Secretary of Labor and Employment shall be included as an additional member of the Climate Change Commission constituted under Section 5 of Republic Act No. 9729, as amended or the “Climate Change Act of 2009”.\nSECTION 8. Appropriations. – The amount necessary to carry out the operation of this Act shall be included in the annual General Appropriations Act.\nSECTION 9. Implementing Rules and Regulations. – Within one hundred eighty (180) days from the effectivity of this Act, the Secretary of Labor and Employment, in coordination with concerned agencies as may be deemed necessary, shall formulate the necessary rules and regulations to implement the provisions of this Act.\nSECTION 10. Separability Clause. – Should any provision of this Act be declared unconstitutional, the remainder thereof not otherwise affected shall remain in full force and effect.\nSECTION 11. Repealing Clause. – Section 5 of Republic Act No. 9729, as amended or the “Climate Change Act of 2009”, is deemed amended or modified by Section 7 of this Act. All other existing laws, presidential decrees, executive orders, proclamations or administrative regulations that are inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly.\nSECTION 12. Effectivity. – This Act shall take effect fifteen (15) days following the completion of its publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Promoting the Creation of Green Jobs, Granting Incentives and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9221"] = {"id":"PH-H9221","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10773_2016.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"将依第 7299 号共和国法授予 Eagle 广播公司的特许经营权再续展二十五年的法案","en":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Eagle Broadcasting Corporation as Provided Under Republic Act No. 7299","orig":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Eagle Broadcasting Corporation as Provided Under Republic Act No. 7299"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10773","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10773_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9221-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the 1987 Philippines Constitution and applicable laws, rules, and regulations, the franchise granted to Eagle Broadcasting Corporation, hereunder referred to as the grantee, and/or its successors amd assignees to construct, install, establish, operate and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations in the Philippines, where frequencies and/or channels ares still available or are assigned for radio and/or television broadcasting, including digital televsion and/or radio systems, through microwave, satellite or the use of any new technological auxiliaries and/or facilities, special broadcast and other program and distribution services and relay stations, is hereby renewed for another twenty-five (25) years from November 3, 2018."}},{"id":"PH-H9221-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. –The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H9221-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission (NTC). – The grantee shall secure from the NTC the appropriate permits and licenses for the operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of such authority."}},{"id":"PH-H9221-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obsence and indecent language, speech, act or scene; or for the dissemination of deliberately false information or willfull misrepresentation, to the detriment of the public interest; or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H9221-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order: to temporarily take over and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national partimony and the use thereof is a privilege confered upon the grantee by the State and may be withdrawn anytime after due process."}},{"id":"PH-H9221-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be in effect for a period of twenty-five (25) years, beginning on November 3, 2018, unless sooner cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9221-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectivity to this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9221-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Self-regulation by and Undertaking of the Grantee. – The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its station: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion, or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willfull failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9221-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of the National and Local Governments. – The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9221-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. – The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corpation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, granting the usufruct of, sale or assignment of franchise or the rights and privileges acquired thereunder within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred, or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H9221-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersal of Ownership. – In accordance with the Constitutional provision to encourage public participation in public utilites, the grantee shall offer to Filippine citizens at least ten percent (10%) of its outstanding capital stock or a higher percentahe that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the time it has achieved the status of a national broadcasting network. A national broadcasting network is hereby defined as one that operates at least three (3) radio/television stations. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9221-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. – The grantee shall comply with and be subject to the provisions of a general broadcast policy kaw which Congress may hereafter enact."}},{"id":"PH-H9221-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Parity Clause. – Any advantage, favor, privilege, exemption, or immunity granted under existing franchise, or which may hereafter be granted for radio and/or televesion broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, That the foregoing shall neither apply to nor affect the provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise: Provided, further, That the foregoing shall not apply to sale, lease, transfer, grant of usufruct, or assignment of legislative franchise with prior Congressional approval."}},{"id":"PH-H9221-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Reportorial Requirement. – The grantee shall submit an annual report the Congress of the Philippines, through the Committee on Legislative Franchise of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of the succeeding year. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9221-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Penalty Clause. – Any grantee who fails to submit the annual report to Congress will be fined five hundred pesos (P500.00) per working day of noncompliance. Said fine shall be collected by the NTC from said delinquent franchise grantee separate from the reportorial penalties imposed by the NTC. The collected funds shall accrue to the monitoring fund of the NTC in line with its supervisory and regulatory functions."}},{"id":"PH-H9221-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. – If any of the sections or provisiongs of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9221-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealability and Nonexclusivity Clause. – This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9221-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Publication. – This Act shall published, through the initiative of the grantee, fifteen (15) days after it has been signed by the President of the Philippines or after it has lapsed into law."}},{"id":"PH-H9221-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Eagle Broadcasting Corporation as Provided Under Republic Act No. 7299","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9222"] = {"id":"PH-H9222","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10774_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布每年3月9日为阿布拉省特别工作假日及学校停课日，以纪念其建省纪念日与Abrenian Kawayan节闭幕","en":"An Act Declaring March 9 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of Abra in Commemoration of Its Foundation Anniversary and the Culmination of the Abrenian Kawayan Festival.","orig":"An Act Declaring March 9 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of Abra in Commemoration of Its Foundation Anniversary and the Culmination of the Abrenian Kawayan Festival."},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10774","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10774_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9222-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"March 9 of every year is hereby declared a special working holiday and no class day in schools in the Province of Abra in commemoration of its foundation anniversary and the culmination of the Abrenian Kawayan Festival."}},{"id":"PH-H9222-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee to his/her regular wage."}},{"id":"PH-H9222-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring March 9 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of Abra in Commemoration of Its Foundation Anniversary and the Culmination of the Abrenian Kawayan Festival.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9223"] = {"id":"PH-H9223","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10775_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"塔盖泰市日","en":"Araw Ng Lungsod Ng Tagaytay","orig":"An Act Declaring June 21 of Every Year a Special Working Holiday and No Class Day in Schools in Tagaytay City, Province of Cavite in Commemoration of Its Founding Day to Be Known as \"Charter Day of Tagaytay City\" or \"Araw Ng Lungsod Ng Tagaytay\""},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10775","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10775_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9223-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"June 21 of every year is hereby declared a special working holiday and no class day in schools in Tagaytay City, Province of Cavite in commemoration of its foundation day to be known as \"Charter Day of Tagaytay City\" or \"Araw ng Lungsod ng Tagaytay\"."}},{"id":"PH-H9223-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee is entitled to his/her regular wage."}},{"id":"PH-H9223-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Araw Ng Lungsod Ng Tagaytay","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9224"] = {"id":"PH-H9224","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10776_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Hermosa市","en":"An Act Declaring May 8 of Every Year as Hermosa Day and a Special Working Holiday and No Class Day in Schools in the Municipality of Hermosa, Province of Bataan","orig":"An Act Declaring May 8 of Every Year as Hermosa Day and a Special Working Holiday and No Class Day in Schools in the Municipality of Hermosa, Province of Bataan"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10776","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10776_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9224-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"May 8 of every year is hereby declared as Hermosa Day and a special working holiday and no class day in schools in the Municipality of Hermosa, Province of Bataan."}},{"id":"PH-H9224-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee is entitled to his/her regular wage."}},{"id":"PH-H9224-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazetter or in a newspaper of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9225"] = {"id":"PH-H9225","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10777_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布每年9月1日为北哥打巴托省特别工作假日及学校停课日，以纪念其建省纪念日的法案","en":"An Act Declaring September 1 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of North Cotabato Commemoration of Its Founding Anniversary","orig":"An Act Declaring September 1 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of North Cotabato Commemoration of Its Founding Anniversary"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10777","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10777_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9225-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"September 1 of every year is declared a special working holiday and no class day in schools in the Province of North Cotabato in commemoration of its founding anniversary. When the holiday falls on a Saturday or a Sunday, the special working day shall be observed on the Monday that follows."}},{"id":"PH-H9225-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee is entitled to his/her regualr wage."}},{"id":"PH-H9225-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring September 1 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of North Cotabato Commemoration of Its Founding Anniversary","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9226"] = {"id":"PH-H9226","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10778_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将帕拉尼亚克市 La Huerta 描笼涯的 Parañaque 国立中学附属校分离，改设为独立的 La Huerta 国立中学，并为此拨款","en":"An Act Separating the Parañaque National High School — La Huerta Annex in Barangay La Huerta, City of Parañaque, Metro Manila From the Parañaque National High School, Converting It Into An Independent National High School to Be Known as La Huerta National High School and Apporiating Funds Therefor","orig":"An Act Separating the Parañaque National High School — La Huerta Annex in Barangay La Huerta, City of Parañaque, Metro Manila From the Parañaque National High School, Converting It Into An Independent National High School to Be Known as La Huerta National High School and Apporiating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10778","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10778_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9226-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Parañaque Nationa High School — La Huerta Annex in Barangay La Huerta, City of Parañaque, Metro Manila is hereby separated from the Parañaque National High School and converted into an independent national high school to be known as La Huerta National High School."}},{"id":"PH-H9226-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Parañaque National High School — La Huerta Annex are hereby transferred to and absorbed by the La Huerta National School."}},{"id":"PH-H9226-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the La Huerta National High School, the initial funding of which shall be charged against the current year's appropriation of the Parañaque National High School — La Huerta Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriation Act."}},{"id":"PH-H9226-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education shall issue rules and regulations necessary to carry out the purpose of this Act."}},{"id":"PH-H9226-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Parañaque National High School — La Huerta Annex in Barangay La Huerta, City of Parañaque, Metro Manila From the Parañaque National High School, Converting It Into An Independent National High School to Be Known as La Huerta National High School and Apporiating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
