  FT["PH-H9229"] = {"id":"PH-H9229","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10781_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Imus市","en":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the City of Imus, Province of Cavite and Appropriating Funds Therefor.","orig":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the City of Imus, Province of Cavite and Appropriating Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10781","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10781_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9229-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Land Transportation Office (LTO) Main Office in Quezon City, a regular district office of the LTO in the City of Imus, Province of Cavite."}},{"id":"PH-H9229-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include int eh Department's programs the operationalization of the LTO Regular District Office in the City of Imus, Province of Cavite, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9229-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9230"] = {"id":"PH-H9230","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10782_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Orani市","en":"An Act Establishing a Regular District Office of the Land Transportation Office in the Municipality of Orani, Province of Bataan and Appropriating Funds Therefor","orig":"An Act Establishing a Regular District Office of the Land Transportation Office in the Municipality of Orani, Province of Bataan and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10782","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10782_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9230-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Theres shall be established, under the Department of Transportation and Communications, a regular district office of the Land Transportation Office (LTO) in the Municipality of Orani, Province of Bataan."}},{"id":"PH-H9230-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department's programs the operationalization of the LTO Regular District's Office in the Municipality of Orani, Province of Bataan, the funding of which shall be included in the annual General Appropriation Act."}},{"id":"PH-H9230-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9231"] = {"id":"PH-H9231","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10783_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Kabacan市","en":"An Act Converting the Kabacan Land Transportation Office (LTO) Extension Office in the Municipality of Kabacan, Province of Cotabato Into a Regular LTO District Office","orig":"An Act Converting the Kabacan Land Transportation Office (LTO) Extension Office in the Municipality of Kabacan, Province of Cotabato Into a Regular LTO District Office"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10783","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10783_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9231-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Kabacan Land Transportation Office (LTO) Extension Office is hereby converted into a regular LTO District Office."}},{"id":"PH-H9231-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department's programs the operationalization of the LTO District Office in the Municipality of Kabacan, Province of Cotabato, the initial funding of which shall be charged against the current year's appropriations of the Kabacan LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H9231-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9232"] = {"id":"PH-H9232","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10784_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Tagaytay市","en":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in the City of Tagaytay, Province of Cavite, Into a Regular District Office and Appropriating Funds Therefor","orig":"An Act Converting the Land Transportation Office (LTO) Extension Office Located in the City of Tagaytay, Province of Cavite, Into a Regular District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10784","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10784_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9232-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office (LTO) Extension Office located in the City of Tagaytay, Province of Cavite, is hereby converted into a regular LTO district office."}},{"id":"PH-H9232-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department's programs the operationalization of the Regular LTO District Office in the City of Tagaytay, Province of Cavite, the initial funding of which shall be charged against the current years's appropriations of the Tagaytay City LTO Extension Office. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H9232-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9233"] = {"id":"PH-H9233","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10785_2016.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"在巴科洛德市设立证券交易委员会（SEC）办事处并为其拨款的法案","en":"An Act Establishing a Securities and Exchange Commission (SEC) Office in Bacolod City and Approriating Funds Therefor","orig":"An Act Establishing a Securities and Exchange Commission (SEC) Office in Bacolod City and Approriating Funds Therefor"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 10785","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10785_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9233-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. — This Act shall be known as the \"SEC Bacolod Office Law\"/"}},{"id":"PH-H9233-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Creation. — There shall established a Securites and Exchange Commission (SEC) Office in Bacolod City."}},{"id":"PH-H9233-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Organization. — The SEC shall immediately include in its programs the organization of the SEC Office in Bacolod City, the funding of which shall be included in the General Appropriations Act.\nThe following ten (10) additional platilla positions are hereby created for the initial operation of the SEC Office in Bacolod City:\nNUMBER OF\nPOSITIONS\nPOSITION/TITLE\nSALARY\nGRADE 1 SEC Extension Office Director 26 1 SEC Executive Assistant 13 1 SEC Clerk/Messenger 10 1 SEC Utility/Driver 9 1 Securities Legal Councel II 19 1 Securities Specialist II 18 1 Securities Specialist I 17 1 SEC Records Specialist II 13 1 SEC Support/Clerical I 10 1 SEC Computer Operator 7 The Department of Budget and Management (DBM) shall immediately issue a Notice of Organization, Staffing, and Compensation Action (NOSCA) or such similar documents necessary for the same purposes: Provided, That nothing in this section shall be construed as to limit the powers of the SEC under determine its own position and classification system and qualification standards."}},{"id":"PH-H9233-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Appropriations. — The sum of ten million pesos (PhP 10,000,000.00), in addition to SEC's current annual budget amd on top of its regular retention income as provided in the Securities Regulation Code, is hereby authorized to be appropriated to the SEC to finance the operation of the SEC Office in Bacolod City for the first fiscal year after the effectivity of this Act.\nFor each fiscal year thereafter, there is authorized to be appropriated to the SEC in the annual General Appropriations Act such additional sums as may be necessary for the continued operation and maintenance of the SEC Office in Bacolod City and such other sums as may be provided by law for the salaries of its officers and employees to reflect pay rate changes made in accordance with the Securities Regulation Code."}},{"id":"PH-H9233-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Implementing Rules and Regulations. — The SEC shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9233-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Separability Clause. — If any section or provision of this Act shall be declared unconstitutional or invalid, the other sections or provisions not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H9233-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Repealing Clause. — All laws, decrees and orders or parts thereof inconsistent herewith are hereby repealed or modified accordinly."}},{"id":"PH-H9233-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Effectivity Clause. — This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a Securities and Exchange Commission (SEC) Office in Bacolod City and Approriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9234"] = {"id":"PH-H9234","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10786_2016.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"宣布每年 9 月第四周为全国甲状腺癌宣传周的法案","en":"An Act Declaring the Fourth Week of September of Every Year as the National Thyroid Cancer Awareness Week","orig":"An Act Declaring the Fourth Week of September of Every Year as the National Thyroid Cancer Awareness Week"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10786","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10786_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9234-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. — This Act shall be known as the \"National Thyroid Cancer Awareness Week Act\"."}},{"id":"PH-H9234-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. — It is the policy of the State to protect and promote the right to health of the people and instill health consciousness among them through public education and awareness programs."}},{"id":"PH-H9234-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Awareness Week. — The fourth week of September of every year is hereby declared the \"National Thyroid Cancer Awareness Week\", in order to coincide with the International Celebration of Thyroid Cancer Awareness Month."}},{"id":"PH-H9234-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Public Education and Awareness Program. — To ensure a meaningful observance of the week as herein declared, a comprehensive public education and awareness program shall be undertaken to discuss the causes, consequences, diagnoses, treatments and prevention of thyroid cancer."}},{"id":"PH-H9234-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Implementing Agency. — The Department of Health (DOH), in coordination with the Thyroid Council of the Philippines (TCP), nongovernment and patients' organizations, shall lead in the implementation of programs and activities for purposes of commemorating this health event."}},{"id":"PH-H9234-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity. — This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring the Fourth Week of September of Every Year as the National Thyroid Cancer Awareness Week","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9235"] = {"id":"PH-H9235","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10787_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Lingig市","en":"An Act Establishing Multi-Species Marine Hatchery in the Municipality of Lingig, Province of Surigao Del Sur and Appropriating Funds Therefor","orig":"An Act Establishing Multi-Species Marine Hatchery in the Municipality of Lingig, Province of Surigao Del Sur and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10787","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10787_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9235-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Bureau of Fisheries and Aquatic Resources of the Department of Agriculture (BFAR-DA), multi-species marine hatchery in the Municipality of Lingig, Province of Surigao del Sur."}},{"id":"PH-H9235-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Within two (2) years after the construction of the multi-species marine hatchery, the BFAR shall, through a memorandum of agreement, transfer its management to the local government unit concerned. It shall implement a training and phasing-in program for local government personnel on the management and operation of the multi-species marine hatchery."}},{"id":"PH-H9235-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Agriculture shall include in the Department's programs the establishment of the mutli-species marine hatchery in the Municipality of Lingig, Province of Surigao del Sur, the funding of which shall be included in the annual General Appropriations Act. The local government units concerned shall set aside funds from any available local revenue in an amount deemed appropriate for its management and operation."}},{"id":"PH-H9235-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Agriculture shall issue the rules and regulations on the supervision and monitoring, and the transfer or withdrawal by the BFAR of the multi-species marine hatchery."}},{"id":"PH-H9235-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9236"] = {"id":"PH-H9236","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10788_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"马里基纳市日","en":"Marikina City Day","orig":"An Act Declaring April 16 of Every Year a Special Holiday and No Class Day in Schools in the City of Marikina in Commemoration of Its Founding Anniversary to Be Known as \"Marikina City Day\""},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10788","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10788_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9236-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"April 16 of every year is hereby declared a special working holiday and no class day is schools in the City of Marikina in commemoration of its founding anniversary to be known as \"Marikina City Day\"."}},{"id":"PH-H9236-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on special working holiday an employee is entitled to his/her regular wage."}},{"id":"PH-H9236-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Marikina City Day","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9237"] = {"id":"PH-H9237","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10789_2016.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"对第 442 号共和国法的修改","en":"An Act Amending Presidential Decree No. 442, as Amended, Otherwise Known as the Labor Code of the Philippines By Adding a New Article 302-A Reducing the Retirement Age of Rachorse Jockeys From Sixty (60) to Fifty-Five (55)","orig":"An Act Amending Presidential Decree No. 442, as Amended, Otherwise Known as the Labor Code of the Philippines By Adding a New Article 302-A Reducing the Retirement Age of Rachorse Jockeys From Sixty (60) to Fifty-Five (55)"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 10789","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10789_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9237-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. — This Act shall be known as the \"Racehorse Jockey Retirement Act\"."}},{"id":"PH-H9237-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. — The State shall promote the welfare of racehorse jockeys recognizing their special circumstance and the inherent dangers of their profession that may cause life-threatening injuries, permanent disability or even death. Towards this end, it is proper that the retirement age of racehorse jockey be appropriately adjusted."}},{"id":"PH-H9237-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Retirement. — The Labor Code of the Philippines is hereby further amended by adding a new Article 302-A to read.\nArt. 302-A. Retirement Age of Racehorse Jockeys. — A professional racehorse jockey who is duly licensed by the Philippine Racing Commission (PHILRACOM) shall be compulsorily retired upon reaching the age of fifty-fice (55) years and shall be entitled to all retirement benefits provided for under Article 302 of this Code: Provided, That he shall pay additional premiums to the Social Security System (SSS) as may be prescribed in the implementing rules and regulations of this Act.\nNothing in this Article shall deprive any racehorse jockey of the benefits he is entitled to under existing laws, company policies or practices.\""}},{"id":"PH-H9237-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation Rules and Regulations. — The Department of Labor and Employment (DOLE), the SSS, and the PHILRACOM, in consultation with the New Philippine Jockeys Association, Inc. (NPJAI) shall promulgate the necessary rules and regulations for the effective implementation of this Act within thirty (30) days from its effectivity."}},{"id":"PH-H9237-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Repealing Clause. — Section 12-B of Republic Act No. 1161, as amended, otherwise known as the Social Security Act of 1997, is hereby amended and modified accordingly to entitle racehorse jockeys to the benefits provided therein upon reaching the retirement age of fifty-five (55) years old. All other laws, decrees, executive orders, proclamations, rules and regulations and other issuances or parts thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H9237-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity Clause. — This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9238"] = {"id":"PH-H9238","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10790_2016.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"修订 Aliw 广播公司的特许经营权并将其期限再延长二十五年，自 2017 年 4 月 13 日起生效的法案","en":"An Act Amending the Franchise of Aliw Broadcasting Corporation and Renewing/extending the Term Thereof to Another Twenty-Five (25) Years That Shall Take Effect on April 13, 2017","orig":"An Act Amending the Franchise of Aliw Broadcasting Corporation and Renewing/extending the Term Thereof to Another Twenty-Five (25) Years That Shall Take Effect on April 13, 2017"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10790","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10790_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1、2、3、4 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9238-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The franchise of Aliw Broadcasting Corporation granted under Republic Act No. 7399 is hereby amended to read as follows:"}},{"id":"PH-H9238-A1-d2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. — Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to Aliw Broadcasting Corporation under Republic Act No. 7399, hereunder referred to as the grantee, its successors or assignees, to construct, install, establish, operate and maintain for commercial purpose and in the public interest, throughout the Philippines, radio and/or television broadcasting stations, including digital television system, through microwave, satellite or whatever means, including the use of any new technologies in television and radio systems, with the corresponding technological auxiliaries and facilities, special broadcast and other progran and distribution services and relay stations."},"dupIndex":2},{"id":"PH-H9238-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. — The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminshing its own right to use to its selected wavelengths or reception thereon as should maximize rendition of the grantee's services and/or availability thereof."}},{"id":"PH-H9238-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. — The grantee shall secure from the National Telecommunciation Commission (NTC), the appropriate permits and licenses for the construction and operation of its station and facilities and shall not use any frequency in the radio/television spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such auhtority."}},{"id":"PH-H9238-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. — The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach thte population on importante public issues; provide at all times sound and balanced programming; promote public participation such as in community programming and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obsence and indecent language, speech, act or scene, or for the dissemination of deliberately false infromation or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H9238-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. — A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order: to temporarily take occer and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public, safety security and public welfare; or to authorize the temporary use nad operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national partimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H9238-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Self-regulation by and Undertaking of Grantee. — The grantee shall not require any previous censorhip of any speech, play, act or scene, or other matter to be broadcast from its stations: Provide, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or sceen, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9238-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Warranty in Favor of National and Local Governments. — The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to person, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9238-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. — The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and priviledges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, grant of usufruct of, sale or assignment of franchise or the rights and privileges acquired thereunder, or of the merger, or transfer of controlling interest of the grantee within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownship shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H9238-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Dispersal of Ownership. — In accordance with the consitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating publuc utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9238-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Equality Clause. — Any advantage, favor, privilege, exemption or immunity granted under existing franchise, or which may hereafter be granted for radio and/or television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, That the foregoing shall neither apply to nor effect provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H9238-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"General Broadcast Policy Law. — The grantee shall comply with and be subject to the provisions of a general broadcast policy law, which Congress may hereafter enact."}},{"id":"PH-H9238-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Reportorial Requirement. — The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its complaince with the term and conditions of the franchise and on its operations on or before April 30 of succeeding year. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9238-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Penalty Clause. — Failure of the grantee to submit the requisite annual report to Congress shall be fined five hundred (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee separate from the reportorial penalties imposed by the NTC."}},{"id":"PH-H9238-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause. — If any of the sections or provisions of this Act is held invalid, all other provision not affected thereby shall remain valid."}},{"id":"PH-H9238-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repeability and Nonexclusivity Clause. — This franchise shall be subject to amendement, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the priviledges herein provided for."}},{"id":"PH-H9238-A2-d2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Renewal/Extension of the Term of Franchise. — The term of the franchise granted under Republic Act No. 7399 is hereby renewed/extended for a period of twenty-five (25) years that shall take effect on April 13, 2017. This franchise shall deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."},"dupIndex":2},{"id":"PH-H9238-A3-d2","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Acceptance and Compliance. — Acceptance of the amendment and extension/renewal of the franchise shall be given in writing to the Congress of the Philippines, through the Committee of Legislative Franchise of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectively of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."},"dupIndex":2},{"id":"PH-H9238-A4-d2","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. — This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."},"dupIndex":2}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Franchise of Aliw Broadcasting Corporation and Renewing/extending the Term Thereof to Another Twenty-Five (25) Years That Shall Take Effect on April 13, 2017","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9239"] = {"id":"PH-H9239","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10791_2016.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将本格特省 Atok 市镇 Caliking 第 30 营地描笼涯的 Atok 国立中学附属校从该校分离，改设为名为 Camp 30 国立中学的独立国立中学并拨款","en":"An Act Separating the Atok National High School - Annex in Barangay Camp 30, Caliking, Municipality of Atok, Province of Benguet From the Atok National High School, Converting It Into An Independent National High School to Be Known as Camp 30 National High School and Appropriating Funds Therefor","orig":"An Act Separating the Atok National High School - Annex in Barangay Camp 30, Caliking, Municipality of Atok, Province of Benguet From the Atok National High School, Converting It Into An Independent National High School to Be Known as Camp 30 National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10791","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-03","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10791_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9239-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Atok National High School — Annex in Barangay Camp 30, Caliking, Municipality of Atok, Province of Benguet is hereby separated from the Atok National High School and coverted into an independent national high school to be known as Camp 30 National High School."}},{"id":"PH-H9239-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Atok National High School — Annex are hereby transferred to and absorbed by the Camp 30 National High School."}},{"id":"PH-H9239-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the Camp 30 National High School, the initial funding of which shall be charged against the current year's appropriation of the Atok National High School — Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H9239-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education shall issue rules and regulations necessary to carry out the purpose of this Act."}},{"id":"PH-H9239-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Atok National High School - Annex in Barangay Camp 30, Caliking, Municipality of Atok, Province of Benguet From the Atok National High School, Converting It Into An Independent National High School to Be Known as Camp 30 National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9240"] = {"id":"PH-H9240","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10792_2016.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"将 Contel 通信公司受让的第 3932 号共和国法特许经营权再续展二十五年，并追认该特许权由 Concepcion 实业公司转让予该公司的法案","en":"An Act Renewing the Franchise of Contel Communications, Incorporated, Assignee of the Grantee Under Republic Act Numbered Thirty-Nine Hundred and Thirty-Two, as Amended By Republic Act Numbered Seventy-Four Hundred and One, Entitled \"An Act Granting the Concepcion Industries, Incorporated a Franchise to Construct, Maintain, and Operate Radiotelephone Stations for the Transmission and Reception of Radio Communications Within the Philippines\" for Another Twenty-Five (25) Years From the Effectivity of This Act and Ratifying the Assignment and Transfer of the Franchise From Concepcion Industries, Incorporated to Contel Communications, Incorporated","orig":"An Act Renewing the Franchise of Contel Communications, Incorporated, Assignee of the Grantee Under Republic Act Numbered Thirty-Nine Hundred and Thirty-Two, as Amended By Republic Act Numbered Seventy-Four Hundred and One, Entitled \"An Act Granting the Concepcion Industries, Incorporated a Franchise to Construct, Maintain, and Operate Radiotelephone Stations for the Transmission and Reception of Radio Communications Within the Philippines\" for Another Twenty-Five (25) Years From the Effectivity of This Act and Ratifying the Assignment and Transfer of the Franchise From Concepcion Industries, Incorporated to Contel Communications, Incorporated"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 10792","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10792_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9240-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to Conception Industries, Incorporated and subsequently assigned and transferred to CONTEL Communications, Incorporated, pursuant to Republic Act No. 3932, entitled \"An Act Granting the Concepcion Industries, Incorporated a Franchise to Construct, Maintain, and Operate Radiotelephone Stations for the Transmission and Reception of Radio Communications Within the Philippines\", and as amended by Republic Act No. 7401, to construct, install, establish, operate, and maintain for commercial purposes and in the public interest, wire and/or wireless telecommunications systems including, but not limited to, mobile, cellular, paging, fiber optics, satellite transmit and receive systems, switches, and their value-added services such as, but not limited to, transmission of voice, data, facsimile, control signs, audio and video, information services bureau and all other telecommunications systems technologies as are at present available or will be made available through technological advances or innovations in the future; and/or construct, acquire, lease and operate or manage transmitting and receiving stations, lines, cables or systems throughout the Philippines, is hereby renewed for another twenty-five (25) years from the effectivity of this Act."}},{"id":"PH-H9240-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H9240-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission (NTC) a Certificate of Public Convenience and Necessity or the appropriate permits and licenses for the construction, installation and operation of its telecommunications systems/facilities. In issuing the certificate, the NTC shall have the power to impose such conditions relative to the construction, operation, maintenance, or service level of the telecommunications system. The NTC shall have the authority to regulate the construction and operation of its telecommunications systems. The grantee shall not use any frequency in the radio spectrum without authorization from the NTC. Such certificate shall state the areas covered and date the grantee shall commence the service. The NTC, however, shall not unreasonably withhold or delay the grant of such authority, permits or licenses."}},{"id":"PH-H9240-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. - For the purpose of erecting and maintaining poles or other supports for said wires or other conductors for the purpose of laying and maintaining underground wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks or bridges of said province, cities and/or municipalities: Provided, however, That a public place, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner by said grantee, its successors or assigns, in accordance with the standards set by the DPWH or the local government unit concerned. Should the grantee, its successors or assigns, after the ten (10)-day notice from the said authority, fail, refuse or neglect to repair or replace any part of public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed or disturbed by the said grantee, its successors or assigns, then the DPWH or the local government unit concerned shall have the right to have the same repaired and replaced in good order and condition at double expense to be charged against the grantee, its successors or assigns."}},{"id":"PH-H9240-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and not use its stations/facilities for obscene or indecent transmission or for dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts.\nThe grantee shall provide basic or enhanced telephone service in any city and/or municipality in the Philippines where it has an approved Certificate of Public Convenience and Necessity for the establishment, operation and maintenance of a local exchange service, without discrimination to any applicant therefor, in the order of the date of their applications, up to the limit of the capacity of its local telephone exchange, and should the demand for the telephone service at any time increase beyond the capacity thereof, the grantee shall increase the same to meet such demand: Provided, That in case the total demand to be satisfied by the expansion is less than the smallest viable local exchange available in the market as determined by the NTC, the grantee shall not be obliged to furnish such service unless the applicant for telephone service defrays the actual expenses for the installation of the telecommunications apparatus necessary for such services and in such case, the NTC may extend the time within which the grantee shall furnish such service.\nThe grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology,"}},{"id":"PH-H9240-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. — The charges and rates for telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the NTC or its legal successor. The rates to be charged by the grantee shall be unbundled, separable and distinct among the services offered and shall be determined in such a manner that regulated services do not subsidize the unregulated ones."}},{"id":"PH-H9240-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order: to temporarily take over and operate the stations, transmitters, facilities or equipment of the grantee; to temporarily suspend the operation of any station, transmitter, facility or equipment in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations, transmitters, facilities or equipment during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H9240-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the date of effectivity of this Act, unless sooner cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years:"}},{"id":"PH-H9240-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Acceptance and Compliance. — Acceptance of this franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9240-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Right of Interconnection. - The grantee is hereby authorized to connect or demand connection of its telecommunications systems to other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the public, under such terms and conditions mutually agreed upon by the parties concerned and the same shall be subject to the review and modification of the NTC."}},{"id":"PH-H9240-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Gross Receipts. - The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the business transacted by it and shall furnish the Commission on Audit (CO A) and the National Treasury a copy of such account not later than the thirty-first (31st) day of January of each year for the preceding twelve (12) months."}},{"id":"PH-H9240-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Books and Accounts. - The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the COA and its duly authorized representatives. It shall be the duty of the grantee to submit to the COA two (2) copies of the quarterly reports on the gross receipts, the net profits and the general condition of the business."}},{"id":"PH-H9240-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Warranty in Favor of the National and Local Governments. -The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, transmitters, facilities and equipment of the grantee."}},{"id":"PH-H9240-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. -The grantee shall not sell, lease, transfer, grant the usufruct of, or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, or merge with any other corporation or entity, or shall transfer the controlling interest of the grantee, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines except when the person or entity to which this franchise is sold, transferred or assigned is a subsidiary or affiliate of the grantee and that at least sixty percent (60%) of the outstanding capital stock entitled to vote of such subsidiary or affiliate is owned and held by Filipino citizens: Provided, That Congress shall be informed of any sale, lease, transfer, grant of usufruct, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger, or transfer of controlling interest of the grantee, within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act.\nA subsidiary or affiliate of the grantee refers to a person that, upon the effectivity of this Act, directly or indirectly, through one (1) or more intermediary corporations, owns more than thirty percent (30%) of the outstanding capital stock of the grantee."}},{"id":"PH-H9240-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9240-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of its franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9240-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Penalty Clause. - Failure of the grantee to submit the requisite annual report to Congress shall be fined five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from said delinquent franchise grantee separate from the reportorial penalties imposed by the NTC."}},{"id":"PH-H9240-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Equality Clause. - Any advantage, favor, privilege, exemption, or immunity granted under other existing franchise, or which may hereafter be granted, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions of telecommunications franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H9240-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Separability Clause. — If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9240-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Repeatability and Nonexclusivity Clause. -This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H9240-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise of Contel Communications, Incorporated, Assignee of the Grantee Under Republic Act Numbered Thirty-Nine Hundred and Thirty-Two, as Amended By Republic Act Numbered Seventy-Four Hundred and One, Entitled \"An Act Granting the Concepcion Industries, Incorporated a Franchise to Construct, Maintain, and Operate Radiotelephone Stations for the Transmission and Reception of Radio Communications Within the Philippines\" for Another Twenty-Five (25) Years From the Effectivity of This Act and Ratifying the Assignment and Transfer of the Franchise From Concepcion Industries, Incorporated to Contel Communications, Incorporated","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9241"] = {"id":"PH-H9241","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10793_2016.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"将依第 7579 号共和国法授予 Radio Veritas-Global 广播公司在菲律宾运营广播电视站的特许经营权再续展二十五年的法案","en":"An Act Renewing the Franchise Granted to Radio Veritas-Global Broadcasting System, Incorporated to Construct, Install, Operate and Maintain for Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and for Other Purposes, Under Republic Act Numbered Seventy-Five Hundred and Seventy-Nine to Another Twenty-Five (25) Years","orig":"An Act Renewing the Franchise Granted to Radio Veritas-Global Broadcasting System, Incorporated to Construct, Install, Operate and Maintain for Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and for Other Purposes, Under Republic Act Numbered Seventy-Five Hundred and Seventy-Nine to Another Twenty-Five (25) Years"},"level":"law","status":"active","topics":["investment","company","trade"],"docNumber":"Republic Act No. 10793","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10793_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9241-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to Radio Veritas-Global Broadcasting System, Incorporated, under Republic Act No. 7579, entitled \"An Act Granting the Radio Veritas-Global Broadcasting System, Incorporated, a Franchise to Construct, Install, Operate and Maintain for Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and for Other Purposes\", and hereunder referred to as the grantee, is hereby renewed for another twenty-five (25) years from the effectivity of this Act."}},{"id":"PH-H9241-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H9241-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. — The grantee shall secure from the National Telecommunications Commission (NTC), tng appropriate permits and licenses for the construction and operation' of its stations and facilities and shall not use any frequency in the radio/television spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H9241-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. -The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations and facilities for the broadcasting of obscene and indecent language, speech, act or scene; or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H9241-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or distrubance of peace and order: to temporarily take over and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process."}},{"id":"PH-H9241-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9241-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9241-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9241-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, city and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9241-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. - The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, granting the usufruct of, sale or assignment of franchise or the rights and privileges acquired thereunder, or of the merger, or transfer of controlling interest, within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H9241-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of itaoutstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncoropliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9241-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadtast Policy Law. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law, which Congress may hereafter enact."}},{"id":"PH-H9241-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Reportorial Requirement. — The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the effectivity of this Act. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9241-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Penalty Clause. - Failure of the grantee to submit the requisite annual report to Congress shall be penalized by a fine in the amount of five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee separate from the reportorial penalties imposed by the NTC. The collected funds shall accrue to the monitoring fund of the NTC in line with its supervisory and regulatory functions."}},{"id":"PH-H9241-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Equality Clause. - Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio and/or television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise: Provided, further, That the foregoing shall not apply to sale, lease, transfer or grant of usufruct of legislative franchise with prior congressional approval."}},{"id":"PH-H9241-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9241-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9241-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted to Radio Veritas-Global Broadcasting System, Incorporated to Construct, Install, Operate and Maintain for Religious, Educational, Cultural and Commercial Purposes Radio and Television Broadcasting Stations in the Philippines, and for Other Purposes, Under Republic Act Numbered Seventy-Five Hundred and Seventy-Nine to Another Twenty-Five (25) Years","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9242"] = {"id":"PH-H9242","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10794_2016.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"将依第 7395 号共和国法授予 Mabuhay 广播系统公司的特许经营权再续展二十五年并扩大为覆盖全菲律宾的广播与电视业务","en":"An Act Renewing for Another Twenty-Five (25) Years and Expanding to Radio/television Broadcasting, National in Scope, Throughout the Philippines, the Franchise Granted to Mabuhay Broadcasting System, Inc. Under Republic Act No. 7395, Entitled \"An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes\"","orig":"An Act Renewing for Another Twenty-Five (25) Years and Expanding to Radio/television Broadcasting, National in Scope, Throughout the Philippines, the Franchise Granted to Mabuhay Broadcasting System, Inc. Under Republic Act No. 7395, Entitled \"An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes\""},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10794","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10794_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9242-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to Mabuhay Broadcasting System, Inc., hereunder referred to as the grantee, its successors or assignees, under Republic Act No. 7395, entitled An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes, to construct, install, establish, operate, and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations, where frequencies and/or channels are still available for radio and/or television broadcasting, including digital television system, through microwave, satellite or whatever means, including the use of any new technology in radio and television systems, with the corresponding technological auxiliaries and facilities, special broadcast and other program, and distribution services and relay stations in the Philippines, is hereby renewed for another twenty-five (25) years from the effectivity of this Act."}},{"id":"PH-H9242-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or availability thereof."}},{"id":"PH-H9242-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission (NTC). - The grantee shall secure from the NTC, the appropriate permits and licenses for the construction and operation of its stations and facilities and shall not use any frequency in the radio/television spectrum without authorization from the NTC. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H9242-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through its broadcasting stations or facilities, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations or facilities for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H9242-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Bight of Government. — A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order: to temporarily take over and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when these shall be so operated.\nThe radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn anytime after due process."}},{"id":"PH-H9242-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the effectivity of this Act, unless sooner revoked or cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9242-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this new franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, within sixty (60) days from the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9242-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral: Provided, further, That willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H9242-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H9242-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. - The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall transfer the controlling interest of the grantee, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any sale, lease, transfer, grant of usufruct of, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger or transfer of the controlling interest of the grantee, within sixty (60) days after the completion of said transaction: Provided, further, That failure to report to Congress Such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred, or assigned, shall be subject to the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H9242-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the aencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9242-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law, which Congress may hereafter enact."}},{"id":"PH-H9242-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of its franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC."}},{"id":"PH-H9242-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Penalty Clause. - Failure of the grantee to submit the requisite annual report to Congress shall be penalized by a fine in the amount of five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee, separate from the reportorial penalties imposed by the NTC."}},{"id":"PH-H9242-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Equality Clause. - Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted for radio and/or television broadcasting, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, That the foregoing shall neither apply to nor affect the provisions of broadcasting franchises concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise."}},{"id":"PH-H9242-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9242-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repeatability and Nonexclusivity Clause. — This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9242-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing for Another Twenty-Five (25) Years and Expanding to Radio/television Broadcasting, National in Scope, Throughout the Philippines, the Franchise Granted to Mabuhay Broadcasting System, Inc. Under Republic Act No. 7395, Entitled \"An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9243"] = {"id":"PH-H9243","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10795_2016.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"将依第 7606 号共和国法授予 Tarlac Electric, Inc. 的特许经营权再延长 25 年的法案","en":"An Act Extending for a Period of Twenty-Five (25) Years the Term of the Franchise Granted to Tarlac Electric, Inc. (Formerly Known as Tarlac Enterprises, Inc.) to Construct, Operate, and Maintain An Electric Light, Heat and Power System in the City of Tarlac, Province of Tarlac, Provided Under Republic Act No. 7606","orig":"An Act Extending for a Period of Twenty-Five (25) Years the Term of the Franchise Granted to Tarlac Electric, Inc. (Formerly Known as Tarlac Enterprises, Inc.) to Construct, Operate, and Maintain An Electric Light, Heat and Power System in the City of Tarlac, Province of Tarlac, Provided Under Republic Act No. 7606"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 10795","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10795_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9243-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. — Subject to the provisions of the 1987 Philippine Constitution and applicable laws, rules and regulations, the franchise granted to Tarlac Electric, Inc. (formerly known as Tarlac Enterprises, Inc.) under Republic Act No. 7606, entitled \"An Act Granting Tarlac Enterprises, Inc. a Franchise to Construct, Operate and Maintain an Electric Light, Heat and Power System in the Municipality of Tarlac, Province of Tarlac, for a Period of Twenty-five (25) Years, and for Other Purposes\", is hereby renewed for another twenty-five (25) years from the effectivity of this Act.\nAs used in this Act, distribution system refers to the systems of wires and associated facilities including subtransmission lines belonging to a franchised distribution utility extending between the delivery point on the national transmission system or generating facility and the metering point/facility of the end-user."}},{"id":"PH-H9243-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Facilities. - All electric distribution facilities, lines, and systems for electric services owned, maintained, operated, or managed by the grantee, its successors or assignees, shall be operated and maintained at all times in a superior manner, and it shall be the duty of the grantee, its successors or assignees, whenever required to do so by the Energy Regulatory Commission (ERC) or its legal successor, or the Department of Energy (DOE) or its legal successor, or any other government agency concerned, to modify, improve, and change the facilities or systems in such a manner and to such extent as the progress in science and improvements in the electric power services may render reasonable and proper.\nWhenever practicable and for purposes of maintaining order, safety, and aesthetics along highways, roads, streets, alleys or right-of-way, the grantee may allow the use of free spaces in its poles, facilities or right-of-way by interested parties upon reasonable compensation to the grantee, considering the cost incurred to accommodate and administer the use of the grantee's facilities by such parties. The ERC shall decide in case of dispute or disagreement between parties."}},{"id":"PH-H9243-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority of the ERC/DOE. - The grantee shall secure from the ERC, DOE or any other government agency which has jurisdiction over the operation of the herein grantee, the necessary certificate of public convenience and necessity and other appropriate permits and licenses for the construction and operation of its electric distribution system."}},{"id":"PH-H9243-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Excavation and Restoration Works. - For the purpose of erecting and maintaining poles, pipes, and other supports for the wires or other conductors for the purpose of laying and maintaining the facilities, wires, cables, pipes, or other conductors, it shall be lawful for the grantee, its successors or assignees, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government unit concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, roads, streets, lines, alleys, avenues, sidewalks, or bridges of the province and city: Provided, however, That a public place, highway, road, street, lane, alley, avenue, sidewalk, or bridge disturbed, altered, or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in workmanlike manner at the expense of the grantee, its successors or assignees, in accordance with the standards set by the DPWH or the local government unit concerned. Should the grantee, its successors or assignees, after the ten (10)-day notice from the grant of authority, fail, refuse or neglect to repair or replace any part of public place, highway, road, street, lane, alley, avenue, sidewalk, or bridge altered, changed, or disturbed by the said grantee, its successors or assignees, then the DPWH or the local government unit concerned shall have the right to have the same repaired and replaced in good order and condition at double expense to be charged against the grantee, its successors or assignees."}},{"id":"PH-H9243-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibility to the Public. - The grantee shall supply electricity to its captive market in the least costly manner. In the interest of the public good and as far as feasible and whenever required by the ERC, the grantee shall modify, improve, or change its facilities, poles, lines, systems and equipment for the purpose of providing efficient and reliable service and reduced electricity costs. The grantee shall charge reasonable and just power rates for its services to all types of consumers within its franchised areas in order that business and industries shall be able to compete.\nThe grantee shall have the obligation to provide open and nondiscriminatory access to its distribution system and services for any end-user within its franchise area consistent with Republic Act No. 9136, otherwise known as the \"Electric Power Industry Reform Act of 2001\". The grantee shall not engage in any activity that will constitute an abuse of market power such as unfair trade practices, monopolistic schemes, and other activities that will hinder competitiveness of business and industries."}},{"id":"PH-H9243-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rates for Services. - The retail rates and charges for the distribution of electric power by the grantee to its end-users shall be regulated by and subject to the approval of the ERC or its legal successor.\nThe grantee shall identify and segregate in its electricity bill to the end-users the components of the retail rate pursuant to Republic Act No. 9136, unless otherwise amended. Such rates charged by the grantee to the end-users shall be made public and transparent. The grantee shall implement lifeline rate to marginalized end-users as mandated under Republic Act No. 9136."}},{"id":"PH-H9243-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Promotion of Consumer Interests. - The herein grantee shall establish a consumer desk that will handle consumer complaints and ensure adequate promotion of consumer interests. The grantee shall act with dispatch on all complaints brought before it."}},{"id":"PH-H9243-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order: to temporarily take over and operate the stations or facilities of the grantee; to temporarily suspend the operation of any station or facility in the interest of public safety, security and public welfare; or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of the stations or facilities during the period when these shall be so operated."}},{"id":"PH-H9243-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Right of Eminent Domain. - Subject to the limitations and procedures prescribed by law, the grantee is authorized to exercise the right of eminent domain insofar as it niay be reasonably necessary for the efficient maintenance and operation of services. The grantee is authorized to install and maintain its poles, wires, and other facilities over and across public property, including streets, highways, forest reserves, and other similar property of the Government of the Philippines, its branches, or any of its instrumentalities. The grantee may acquire such private property as is actually necessary for the realization of the purposes for which this franchise is granted: Provided, That proper expropriation proceedings shall have been instituted and just compensation paid."}},{"id":"PH-H9243-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Term of Franchise. - This franchise shall be in effect for a period of twenty-five (25) years from the date of effectivity of this Act, unless sooner cancelled. This franchise shall be deemed ipso facto revoked in the event the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H9243-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate within sixty (60) days from the effectivity of this Act. Upon such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H9243-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Warranty in Favor of the National and Local Governments. - The grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction, installation, operation, and maintenance of the distribution system of the grantee."}},{"id":"PH-H9243-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Liability for Damages. - The grantee shall be liable for any injury and damage arising from or caused by accident to persons and property by reason of any defective construction under this franchise or of any neglect or omission to keep its poles and wires in safe condition."}},{"id":"PH-H9243-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. - The grantee shall not sell, lease, transfer, grant the usufruct of, or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation, or other commercial or legal entity, or merge with any other corporation, or entity, or shall transfer the controlling interest of the grantee, whether as a whole or in parts, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation, or entity without the prior approval of the Congress of the Philippines: Provided, That Congress shall be informed of any lease, transfer, granting the usufruct of, sale, or assignment of franchise or the rights and privileges acquired thereunder, or of the merger, or sale of the controlling interest within sixty (60) days after the completion of said transaction: Provided, further, That any such transfer, sale, or assignment is in accordance with the constitutional limitations: Provided, furthermore, That failure to report to Congress such change of ownership shall render the franchise ipso facto revoked: Provided, finally, That any person or entity to which this franchise is sold, transferred, or assigned, shall be subject to the same, conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H9243-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) of its outstanding capital stock or a higher percentage that may hereafter be provided by law in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, establishment of cooperatives and other methods of encouraging public participation by citizens and corporations operating public utilities must be implemented. Noncompliance therewith shall render the franchise ipso facto revoked."}},{"id":"PH-H9243-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of the franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the ERC."}},{"id":"PH-H9243-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Penalty Clause. - The failure of the grantee to submit the requisite annual report to Congress shall be penalized by a fine in the amount of five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the ERC from the delinquent franchise grantee separate from the reportorial penaltiesimposed by the ERC. All proceeds from the fines or penalties shall accrue to the monitoring fund of the ERC in line with its supervisory and regulatory functions."}},{"id":"PH-H9243-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Equality Clause. - Any advantage, favor, privilege, exemption, or immunity granted under existing franchises, or which may hereafter be granted, upon prior review and approval of Congress, shall become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee: Provided, however, That the foregoing shall neither apply to nor affect provisions concerning territory covered by the franchise, the life span of the franchise or the type of service authorized by the franchise: Provided, further, That the foregoing shall not apply to the sale, lease, transfer, grant of usufruct, or assignment of legislative franchises with prior congressional approval."}},{"id":"PH-H9243-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Applicability Clause. - The grantee shall comply with and be subject to the provisions of Commonwealth Act No. 146, as amended, otherwise known as the \"Public Service Act\" and Republic Act No. 9136, otherwise known as the \"Electric Power Industry Reform Act of 2001\"."}},{"id":"PH-H9243-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9243-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repeatability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H9243-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Extending for a Period of Twenty-Five (25) Years the Term of the Franchise Granted to Tarlac Electric, Inc. (Formerly Known as Tarlac Enterprises, Inc.) to Construct, Operate, and Maintain An Electric Light, Heat and Power System in the City of Tarlac, Province of Tarlac, Provided Under Republic Act No. 7606","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9244"] = {"id":"PH-H9244","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10796_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"宣布新比斯开省Sta. Fe的Balete山口为国家纪念地，名称为Balete山口国家纪念地的法案","en":"An Act Declaring the Balete Pass in Sta. Fe, Nueva Vizcaya as a National Shrine to Be Known as the Balete Pass National Shrine","orig":"An Act Declaring the Balete Pass in Sta. Fe, Nueva Vizcaya as a National Shrine to Be Known as the Balete Pass National Shrine"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10796","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10796_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9244-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Balete Pass in Sta. Fe, Nueva Vizcaya, more particularly described as follows, is hereby declared as a national shrine to be known as the Balete Pass National Shrine. A parcel of land situated at Barangay Tactac, Sta. Fe, Nueva Vizcaya, bounded on the east, along lines 10-20 by Lot 1329, Lot 1327 and Lot 1325, CAD No. 768-D; on the south, along lines 1-2 by portion of the Talavera River Watershed Forest Reserve; on the west, along lines 2-7 by the Wildlife Sanctuary; on the north, along lines 7-10 by the Balete Pass Forest Reserve; Thence 1-2\nS. 74\" 09' W.\n400.00 m.\n2-3\nN. 33\" 59' W.\n360.00 m.\n3-4\nN. 85\" 40' W.\n390.39 m.\n4-5\nN. 04\" 20' E.\n80.00 m.\n5-6\nN. 73\" 35' E.\n282.73 m.\n6-7\nN. 33\" 59' W.\n180.00 m.\n7-8\nN. 78\" 20' E.\n550.00 m 8-9\nS. 77\" 10' E.\n270.00 m.\n9-10\nN. 68\" 41' E.\n136.90 m.\n10-11\nS. 13\" 59' E.\n127.70 m.\n11-12\nS. 04\" 54' E.\n106.34 m.\n12-13\nS. 13\" 38' W.\n16.59 m.\n13-14\nS. 13\" 25' E.\n184.23 m.\n14-15\nS. 11\" 01' W.\n21.63 m.\n15-16\nS. 13\" 46' W.\n21.76 m.\n16-17\nS. 60\" 47' E.\n45.01 m.\n17-18\nS. 17\" 16' W.\n7.95 m.\n18-19\nS. 41\" 09' W.\n111.13 m.\n19-20\nN. 71\" 17' W.\n21.02 m.\n20-21\nS. 69\" 14' W.\n154.12 m. containing an area of five hundred fifty-seven thousand seven hundred eighty-nine square meters (557,789 sq.m.), more or less. The administration and maintenance of the Balete Pass National Shrine shall be under the Philippine Veterans Affairs Office."}},{"id":"PH-H9244-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of National Defense shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9244-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the implementation of this Act shall be charged against the current year's appropriations of the Philippine Veterans Affairs Office under the Department of National Defense. Thereafter, such amount as may be needed for the maintenance of the Balete Pass National Shrine shall be included in the annual General Appropriations Act."}},{"id":"PH-H9244-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring the Balete Pass in Sta. Fe, Nueva Vizcaya as a National Shrine to Be Known as the Balete Pass National Shrine","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9245"] = {"id":"PH-H9245","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10797_2016.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将宿务省Consolacion的菲律宾公共安全学院第七区域培训学校（PPSC-RTS 7）更名为国家警察培训学院Camp Jesse M. Robredo第七区域培训中心的法案","en":"An Act Renaming the Philippine Public Safety College - Regional Training School 7 (Ppsc-Rts 7) in Consolacion, Province of Cebu Into the Camp Jesse M. Robredo Regional Training Center 7, National Police Training Institute, Philippine Public Safety College","orig":"An Act Renaming the Philippine Public Safety College - Regional Training School 7 (Ppsc-Rts 7) in Consolacion, Province of Cebu Into the Camp Jesse M. Robredo Regional Training Center 7, National Police Training Institute, Philippine Public Safety College"},"level":"law","status":"active","topics":["education","defence"],"docNumber":"Republic Act No. 10797","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10797_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9245-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Public Safety College-Regional Training School 7 (PPSC-RTS 7) in Consolation, Province of Cebu is hereby renamed the Camp Jesse M. Robredo Regional Training Center 7, National Police Training Institute, Philippine Public Safety College."}},{"id":"PH-H9245-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of the Interior and Local Government shall issue the necessary rules, orders and circulars to implement the provision of this Act."}},{"id":"PH-H9245-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, executive orders, decrees, instructions, rules and regulations contrary to or inconsistent with any provision of this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H9245-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renaming the Philippine Public Safety College - Regional Training School 7 (Ppsc-Rts 7) in Consolacion, Province of Cebu Into the Camp Jesse M. Robredo Regional Training Center 7, National Police Training Institute, Philippine Public Safety College","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9246"] = {"id":"PH-H9246","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10798_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Antipolo市","en":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the City of Antipolo, Province of Rizal and Appropriating Funds Therefor","orig":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the City of Antipolo, Province of Rizal and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10798","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10798_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9246-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a regular district office of the Land Transportation Office (LTO) in the City of Antipolo, Province of Rizal."}},{"id":"PH-H9246-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department's programs the operationalization of the LTO District Office in the City of Antipolo, Province of Rizal the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9246-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9247"] = {"id":"PH-H9247","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10799_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在东内格罗斯省La Libertad市镇设立陆运署（LTO）正式区办公室，并为此拨款及为其他目的法案","en":"An Act Establishng a Regular District Office of the Land Transpoetation Office (LTO) in the Municipality of La Libertad, Province of Negros Oriental, Appropriating Funds Therefoe and for Other Purposes","orig":"An Act Establishng a Regular District Office of the Land Transpoetation Office (LTO) in the Municipality of La Libertad, Province of Negros Oriental, Appropriating Funds Therefoe and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10799","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10799_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9247-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Land Transportation Office (LTO) Main Office in Quezon City, a regular district office of the LTO in the Municipality of La Iibertad, Province of Negros Oriental."}},{"id":"PH-H9247-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation and Communications shall immediately include in the Department's programs the operationalization of the LTO Regular District Office in the Municipality of La Iibertad, Province of Negros Oriental, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9247-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishng a Regular District Office of the Land Transpoetation Office (LTO) in the Municipality of La Libertad, Province of Negros Oriental, Appropriating Funds Therefoe and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9248"] = {"id":"PH-H9248","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10800_2016.html","fetchedAt":"2026-10-06","articleCount":28,"structureMode":"ARTICLE","title":{"zh":"设立Camiling市","en":"An Act Converting the Tarlac College of Agriculture (Tca) in the Municipality of Camiling, Province of Tarlac Into a State University to Be Known as the Tarlac Agricultural University and Appropriating Funds Therefor","orig":"An Act Converting the Tarlac College of Agriculture (Tca) in the Municipality of Camiling, Province of Tarlac Into a State University to Be Known as the Tarlac Agricultural University and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","environment","culture"],"docNumber":"Republic Act No. 10800","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 28 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10800_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9248-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion. - The Tarlac College of Agriculture (TCA) in the Municipality of Camiling, Province of Tarlac is hereby converted into a state university to be known as the Tarlac Agricultural University, hereinafter referred to as the University."}},{"id":"PH-H9248-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"General Mandate. — The University shall primarily provide advance education, higher technological and professional instruction and training in the fields of agriculture, agribusiness management, science and technology, engineering, teacher education, nontraditional courses, and other relevant fields of study. It shall also undertake research, extension services, and production activities in support of the development of the Province of Tarlac, and provide progressive leadership in its areas of specialization."}},{"id":"PH-H9248-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Academic Freedom and Institutional Autonomy. - The University shall enjoy academic freedom and institutional autonomy pursuant to paragraph 2, Section 5 of Article XIV of the Constitution of the Republic of the Philippines."}},{"id":"PH-H9248-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Curricular Offerings. - The University shall offer undergraduate and graduate courses in the fields of agriculture, agribusiness management, science and technology, agricultural and other branches of engineering, and other courses within its areas of specialization, and according to its capabilities as the Board may deem necessary to carry out its objectives, particularly in meeting the needs of the Province of Tarlac and Region III.\nThe University may operate a reasonably-sized laboratory school under its College of Education."}},{"id":"PH-H9248-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Administration. - The University shall have the general powers of a corporation set forth in Batas Pambansa Blg. 68, as amended, otherwise known as \"The Corporation Code of the Philippines\". The administration of the University and the exercise of its corporate powers shall be vested exclusively in the Board of Regents and the President of the University."}},{"id":"PH-H9248-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Governing Board. - The governing board of the University shall be the Board of Regents, hereinafter referred to as the Board, which shall be composed of the following:\n(a) The Chairperson of the Commission on Higher Education (CHED), Chairperson;\n(b) The President of the University, Vice Chairperson;\n(c) The Chairperson of the Committee on Education, Arts and Culture of the Senate, member;\n(d) The Chairperson of the Committee on Higher and Technical Education of the House of Representatives, member;\n(e) The Regional Director of the National Economic and Development Authority (NEDA), member;\n(f) The Regional Director of the Department of Agriculture (DA), member;\n(g) The President of the federation of faculty associations ofthe University, member;\n(h) The President of the federation of student councils of the University, member;\n(i) The President of the federation of alumni associations of the University, member; and\n(j) Two (2) prominent citizens from the private sector who have distinguished themselves in their profession or fields of specialization, members.\nThe Board shall appoint the two (2) prominent citizens from among a list of at least five (5) qualified persons in the Province of Tarlac, as recommended by the search committee, in consultation with the Chairperson of the CHED and the other members of the Board, based on the standards and qualifications for the position.\nThe Presidents of the federation of faculty associations, the federation of student councils and the federation of alumni associations shall serve in the Board only for the duration of their respective terms of office, as set forth in their respective constitutions and bylaws.\nThe two (2) prominent citizens shall serve for a term of two (2) years from the date of appointment."}},{"id":"PH-H9248-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Powers and Duties of the Board. - The Board shall, in addition to its general powers of administration and the exercise of all the powers granted to the board of directors of a corporation under existing laws, have the following specific powers and duties:\n(a) Promulgate and implement policies in accordance with the declared State policies and the provisions of the Philippine Constitution on education, agriculture, science and technology, as well as the policies, standards and thrusts of the CHED under Republic Act No. 7722, otherwise known as the \"Higher Education Act of 1994\";\n(b) Promulgate rules and regulations not contrary to law as may be necessary to carry out the purposes and functions of the University;\n(c) Receive and appropriate all sums as may be provided for the support of the University in the manner it may determine in its discretion, in order to carry out the purposes and functions of the University;\n(d) Import economic, technical and cultural books and publications;\n(e) Receive in trust, legacies, gifts and donations of real and personal properties of all kinds, and to administer and dispose of the same, when necessary, for the benefit of the University, and subject to the limitations, directions and instructions of the donor, if any;\n(f) Fix the tuition fees and other necessary school charges such as matriculation fees, graduation fees, and laboratory fees, as the Board may deem proper to impose, after due consultations with the involved sectors.\nSuch fees and charges, including government subsidies and other income generated by the University, shall constitute a special trust fund and shall be deposited in any authorized government depository bank, and all interests that shall accrue therefrom shall form part of the same funds for the use of the University.\nAny provision of existing laws, rules and regulations to the contrary notwithstanding, any income generated by the University from tuition fees and other charges, as well as from the operation of auxiliary services and land grants, shall be retained by the University and may be disbursed by the Board for instruction, research, extension or other programs/projects of the University: Provided, That all fiduciary fees shall be disbursed for the specific purposes for which these are collected.\nIf, for reasons beyond its control, the University shall not be able to pursue any project for which the funds have been appropriated and allocated under its approved program of expenditures, the Board may authorize the use of said funds for any reasonable purpose which, in its discretion, may be necessary and urgent for the attainment of the objectives and goals of the University;\n(g) Adopt and implement a socialized scheme of tuition and other school fees for greater access to education of poor but deserving students;\n(h) Authorize the construction or repair of its buildings, machinery, equipment, and other facilities, and the purchase and acquisition of real property, including necessary supplies, materials, and equipment;\n(i) Appoint, upon the recommendation of the President of the University, vice presidents, deans, directors, heads of campuses, faculty members, and other officials and employees of the University;\n(j) Fix and adjust the salaries of faculty members, administrative officials and employees, subject to the provisions of the Revised Compensation and Position Classification System and other pertinent budget and compensation laws governing hours of service, and such other duties and conditions as it may deem proper; grant them, at its discretion, leaves of absence under such regulations as it may promulgate, any provision of existing law to the contrary notwithstanding; and remove them for cause in accordance with the requirements of due process of law;\n(k) Approve the curricula, instructional programs, and rules of discipline drawn by the Administrative and Academic Councils herein provided;.\n(l) Set policies on admission and graduation of students;\n(m) Award honorary degrees upon persons in recognition of their outstanding contribution in the fields of education, public service, arts, science and technology, agriculture or in any field of specialization within the academic competence of the University, and authorize the awarding of certificates of completion of nondegree and nontraditional courses;\n(n) Establish and absorb non-chartered tertiary institutions within the Province of Tarlac as branches and centers, in coordination with the CHED and in consultation with the Department of Budget and Management (DBM), and offer therein programs or courses in order to carry out the constitutional mandate of providing equal access to educational opportunities;\n(o) Establish research and extension centers to promote the development of the University;\n(p) Establish professorial chairs in the University and provide fellowships for qualified faculty members, and scholarships to deserving students;\n(q) Delegate any of its powers and duties to the President and other officials of the University, as it may deem appropriate, so as to expedite the administration of the affairs of the University;\n(r) Authorize an external management audit of the University, to be financed by the CHED, subject to the rules and regulations of the Commission on Audit (COA), and institute reforms, including academic and structural changes, on the basis of the audit results and recommendations;\n(s) Collaborate with governing boards of other state universities and colleges within the Province of Tarlac or Region III, under the supervision of the CHED and in consultation with the DBM, and work towards the restructuring of the University to become more efficient, relevant, productive, and competitive;\n(t) Enter into joint ventures with business and industry for the profitable development and management of the economic assets of the University, the proceeds from which shall be used for the development and strengthening of the University;\n(u) Develop consortia and other economic forms of linkages with local government units (LGUs), institutions and agencies, both public and private, local and foreign, in the furtherance of the purposes and objectives of the University;\n(v) Develop academic arrangements for institutional capability building with appropriate institutions and agencies, public and private, local and foreign, and appoint experts/specialists as consultants, part-time or visiting or exchange professors, scholars or researchers, as the case may be;\n(w) Set up the adoption of modern and innovative modes of transmitting knowledge such as the use of information technology, the dual training system, open distance learning, and community laboratory for the promotion of greater access to education;\n(x) Establish policy guidelines and procedures for participative decision-making and transparency within the University;\n(y) Outsource, where most advantageous to the University, the management of nonacademic services such as health, food, building or grounds or property maintenance, and such other similar activities; and\n(z) Extend the term of the President of the University, whose performance has been rated by the Board as outstanding, beyond the age of retirement but not beyond the age of seventy (70), upon the unanimous recommendation of the search committee."}},{"id":"PH-H9248-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Meetings of the Board. - The Board shall regularly convene once every three (3) months. Whenever necessary, the Chairperson of the Board may call a maximum of two (2) special meetings within the same period, upon three (3) days' prior written notice.\nA quorum of the Board shall consist of majority of all its members holding office at the time of the meeting: Provided, That the Chairperson of the Board or the President of the University is among those present in the meeting.\nIn the absence of the Chairperson of the CHED, a Commissioner of the CHED, duly designated by the CUED Chairperson, shall represent the CHED Chairperson in the meeting, with all the rights and responsibilities of a regular member: Provided, That during this meeting, the President of the University, as Vice Chairperson, shall be the Presiding Officer: Provided, further, That this provision notwithstanding, the Chairperson of the CHED is hereby authorized to designate a CHED Commissioner as the regular Chairperson of the Board, in which case the said CHED Commissioner shall act as the Presiding Officer.\nIn case the Chairpersons of the Senate Committee on Education, Arts and Culture and the House Committee on Higher and Technical Education will not be able to attend the board meeting, they may duly designate their respective representatives to attend the meeting, who shall have the same rights and responsibilities as regular members of the Board.\nThe members of the Board shall not receive any salary, but shall be entitled to reimbursements for actual and necessary expenses incurred, either in their attendance to meetings of the Board or in connection with other official business authorized by resolution of the Board, subject to existing laws and regulations."}},{"id":"PH-H9248-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The University President. - The University shall be headed by a President, who shall render full-time service and who shall be appointed by the Board, subject to the guidelines, qualifications, and standards set by the Board, upon the recommendation of a duly constituted search committee. The University President shall serve a term of four (4) years and shall be eligible for reappointment for another term: Provided, That in order to effect a smooth transition to a state university, the incumbent President of the TCA shall serve as the first President of the University.\nWithin six (6) months before the expiration of the term of office of the incumbent President of the University, the Board shall constitute the Search Committee for the Presidency (SCP).\nThe Board shall designate an Officer-in-Charge of the University in case of a vacancy in the Office of the President by reason of death, compulsory retirement, resignation, removal for cause, or incapacity of the President to perform the functions of the office, pending the appointment of a new President: Provided, That the Officer-in-Charge shall serve only the unexpired portion of the term.\nThe powers and duties of the President of the University, in addition to those provided in this Act, shall be those usually pertaining to the Office of the President of similar universities, and those delegated by the Board.\nThe salary of the President of the University shall be in accordance with the Revised Compensation and Position Classification System, as modified by Joint Resolution No. 4 dated June 17, 2009, and other pertinent budget and compensation laws, and shall be comparable to that being received by the Presidents of similar educational institutions.\nThe President of the University shall be assisted by a Vice President for Academic Affairs, a Vice President for Finance and Administration, and a Vice President for Research, Extension and Training, who shall be appointed by the Board upon the recommendation of the President."}},{"id":"PH-H9248-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Secretary of the University. - The Board shall appoint a Secretary, who shall serve as such for both the Board and the University, and shall keep all records and proceedings of the Board in addition to other duties and responsibilities. The Secretary of the University shall serve upon each member of the Board the appropriate notice of the Board meetings."}},{"id":"PH-H9248-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Treasurer of the University. - The Treasurer of the Philippines shall be the ex officio Treasurer of the University."}},{"id":"PH-H9248-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The Administrative Council. - There shall be an Administrative Council consisting of the President of the University as Chairperson, vice presidents, deans, directors and other officials of equal rank as members, whose duty is to review and recommend to the Board the policies governing the administration, management, and development planning of the University."}},{"id":"PH-H9248-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Academic Council. - There shall be an Academic Council to be composed of the President of the University, who shall act as Chairperson, and all of the academic staff with the rank of at least an assistant professor, as members.\nThe Academic Council shall have the power to review and recommend the curricular offerings and rules of discipline of the University, subject to the approval of the Board. It shall fix the requirements for the admission of students, as well as for their graduation and conferment of degrees, subject to the review and approval of the Board, through the President of the University. It shall have the disciplinary power over the students of the University, and shall formulate academic policies, and rules and regulations on discipline, subject to the approval of the Board."}},{"id":"PH-H9248-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Faculty. - No political belief, gender preference, cultural or community affiliation or ethnic origin, and religious opinion or affiliation shall be a matter of inquiry in the appointment of faculty members of the University: Provided, That the appointment shall be subject to the guidelines, qualifications, and standards set by the Board: Provided, further, That no member of the faculty shall teach for or against any particular church or religious sect."}},{"id":"PH-H9248-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Scholarship Program/Admission. - The University shall provide a scholarship program and other affirmative action programs to assist poor but deserving students who qualify for admission to the University.\nNo student shall be denied admission to the University by reason of sex, religion, cultural or community affiliation or ethnic origin."}},{"id":"PH-H9248-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Authority to Loan or Transfer Apparatus/ Equipment/Supplies and Detail of Personnel. — The heads of the bureaus and offices of the national government are hereby authorized to loan or transfer, upon the request of the President of the University, such apparatus, equipment or supplies as may be needed by the University, and to detail employees for duty therein when, in the judgment of the head of the bureau or office, such apparatus, equipment, supplies or services of such employees can be spared without serious detriment to public service.\nThe employees so detailed shall perform such duties as required of them by the President of the University, and the time so employed shall be counted as part of their regular services."}},{"id":"PH-H9248-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Assets, Liabilities and Personnel. - All assets, real and personal, personnel and records of the TCA, as well as liabilities or obligations, are hereby transferred to the University: Provided, That the positions, rights and security of tenure of faculty members and personnel therein employed under existing laws prior to the conversion into a university shall be respected: Provided, further, That the incumbents of the positions shall remain in the same status until otherwise provided for by the Board: Provided, finally, That the College shall also include an upgrade or increase in its human resource component.\nAll parcels of land belonging to the government occupied by the TCA are hereby declared to be property of the University, and shall be titled under that name: Provided, That should the University cease to exist or be abolished or should such parcels of land aforementioned be no longer needed by the University, the same shall revert to the LGU concerned or to the Republic of the Philippines, as the case may be."}},{"id":"PH-H9248-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Tax Exemption. — The importation of economic, technical and cultural books and publications, which is for economic, technical, vocational, scientific philosophical, historical or cultural purposes made by the University, upon certification by the CHED, shall be exempt from customs duties in accordance with the provisions of the Tariff and Customs Code of the Philippines, as amended.\nAll grants, bequests, endowments, donations and contributions made to the University, to be used actually, directly and exclusively by the University, shall be exempt from the donor's tax and the same shall be allowed as deduction from the gross income of the donor for purposes of computing the taxable income of the donor, in accordance with the provisions of the National Internal Revenue Code of 1997, as amended."}},{"id":"PH-H9248-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Appropriations. - The amount necessary to carry out the provisions of this Act shall be charged against the current year's appropriations of the TCA, except the sums needed for the continued operation of the existing high school. Thereafter, such sums as may be necessary for the continued operation and maintenance of the University shall be included in the annual General Appropriations Act."}},{"id":"PH-H9248-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Development Plan, Management Audit, Organizational/Administrative/Academic Structure. - Within the period of one hundred twenty (120) days after the approval of this Act, the University shall accomplish the following:\n(a) Submit a five (5)-year development plan, including its corresponding program budget to the CHED, for corresponding recommendation to the DBM;\n(b) Undergo a management audit in cooperation with the CHED; and\n(c) Set up its organizational, administrative, as well as academic structure, including the appointment of key officials of the University."}},{"id":"PH-H9248-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Annual Report. - On or before the fifteenth (15th) day of the second (2nd) month after the opening of the regular classes each year, the Board shall file with the Office of the President of the Philippines and both Houses of Congress, through the Chairperson of the CHED, a detailed report on the progress, conditions and needs of the University."}},{"id":"PH-H9248-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Suppletory Application. - The provisions of Republic Act No. 8292, otherwise known as the \"Higher Education Modernization Act of 1997\", shall be an integral part of this Act and shall serve as part of the Governing Charter of the University."}},{"id":"PH-H9248-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Compliance with CHED Requirements. - The provisions of this Act notwithstanding, the conversion of the institution into a university, shall become effective only upon the determination and declaration by the CHED, based on the recommendation of a panel of experts it shall constitute for the purpose, that the institution has complied with the requirements for a university status based on CHED Memorandum Order No. 46, series of 2012 (Policy-Standard to Enhance Quality Assurance), in Philippine Higher Education, through an Outcomes-Based and Typology-Based Quality Assurance: Provided, That the panel may issue such a recommendation when the institution has substantially complied with the requirements for the grant of university status.\nThe following operational requirements for a university as established by the CHED shall be complied with:\n(a) Faculty members who possess relevant degrees in their areas of specialization as required by the CHED, and who must have participated in research and development activities in their respective disciplines, as evidenced by refereed publications and other scholarly outputs;\n(b) A comprehensive range of degree programs in all levels, from basic post-secondary to doctoral programs;\n(c) Viable research programs in specific (disciplinal and multidisciplinary) areas of study that produce new knowledge as evidenced by refereed publications, citations, inventions, and patents, among others;\n(d) Comprehensive learning resources and support structures (e.g. libraries, practicum laboratories, relevant educational resources, and linkages with the relevant disciplinal and professional sectors) to allow students to explore basic, advance, and even cutting edge knowledge in a wide range of disciplines or professions;\n(e) Active and ongoing linkage and affiliation with other research institutions in various parts of the world that would ensure that the research activities of the university are functioning at current global standards; and\n(f) Outreach activities that allow the students, faculty, and research staff to apply the new knowledge they generate to address specific social development problems broadly defined.\nThe institution shall retain its status prior to the effectivity of this Act, unless in the meantime it is able to comply with the requirements provided herein, within a period not later than January 01, 2020."}},{"id":"PH-H9248-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Parity Clause. — All other powers, functions and privileges, responsibilities and limitations to state universities and their officials under existing laws shall be deemed granted to or imposed upon the University and its officials, whenever appropriate."}},{"id":"PH-H9248-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Implementing Rules and Regulations. -Within sixty (60) days from the effectivity of this Act, the Board, in consultation with the CHED, shall formulate the rules and regulations to fully implement the provisions of this Act."}},{"id":"PH-H9248-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Separability Clause. - If, for any reason, any part or provision of this Act is declared invalid or unconstitutional, the remaining parts or provisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H9248-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Repealing Clause. — All laws, presidential decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H9248-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131"};
  FT["PH-H9249"] = {"id":"PH-H9249","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10801_2016.html","fetchedAt":"2026-10-06","articleCount":61,"structureMode":"ARTICLE","title":{"zh":"规范海外劳工福利管理局运营与管理的法案","en":"An Act Governing the Operations and Administration of the Overseas Workers Welfare Administration","orig":"An Act Governing the Operations and Administration of the Overseas Workers Welfare Administration"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 10801","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 61 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10801_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9249-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. – This Act shall be known as the “Overseas Workers Welfare Administration Act”."}},{"id":"PH-H9249-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is the policy of the State to afford full protection to labor, local and overseas, organized and unorganized, and promote full employment opportunities for all. Towards this end, it shall be the State’s responsibility to protect the Overseas Filipino Workers (OFWs).\nThe Overseas Workers Welfare Administration (OWWA) shall be one of the principal agencies of the State to serve and promote the rights, interest and welfare of the OFWs and their families.\nWelfare assistance, services, and programs provided by the OWWA shall be gender-responsive, taking into consideration the different impacts of labor migration to men and women."}},{"id":"PH-H9249-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Objectives. – This Act is enacted to provide guidelines on matters concerning the OWWA, its mandate, purposes and objectives, membership, collection of contributions, and availment of benefits and services. This Act also embodies the policies on fund management, programs and services administration.\nNATURE, SCOPE AND FUNCTIONS OF THE OWWA"}},{"id":"PH-H9249-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Nature of the OWWA. – The OWWA is a national government agency vested with the special function of developing and implementing welfare programs and services that respond to the needs of its member-OFWs and their families. It is endowed with powers to administer a trust fund to be called the OWWA Fund. Being a chartered institution, the OWWA shall not fall under any of the following categories: government instrumentalities with corporate powers (GICPs), government corporate entities (GCEs), government financial institutions (GFIs) and/or government-owned or -controlled corporations (GOCCs).\nThe OWWA shall be an attached agency of the Department of Labor and Employment (DOLE). Its officials and employees are covered by the Salary Standardization Law."}},{"id":"PH-H9249-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Scope. – This Act shall apply to the OWWA, the OWWA Secretariat, the OWWA Fund, to its member-OFWs and those who will avail of the voluntary membership program of the OWWA, and to overseas recruitment/manning agencies/employers who are duly registered with the Philippine Overseas Employment Administration (POEA)."}},{"id":"PH-H9249-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Functions. – The OWWA shall exercise the following functions:\n(a) To protect the interest and promote the welfare of member-OFWs in all phases of overseas employment in recognition of their valuable contribution to the overall national development effort;\n(b) To facilitate the implementation of the provisions of the Labor Code of the Philippines (Presidential Decree No. 442, as amended) and the Migrant Workers and Overseas Filipinos Act of 1995 (Republic Act No. 8042, as amended), concerning the responsibility of the government to promote the well-being of OFWs. Pursuant thereto, and in furtherance thereof, it shall provide legal assistance to member-OFWs;\n(c) To provide social and welfare programs and services to member-OFWs, including social assistance, education and training, cultural services, financial management, reintegration, and entrepreneurial development services;\n(d) To provide prompt and appropriate response to global emergencies or crisis situations affecting OFWs and their families;\n(e) To ensure the efficiency of collections and the viability and sustainability of the OWWA Fund through sound, judicious, and transparent investment and management policies;\n(f) To undertake studies and researches for the enhancement of the social, economic, and cultural well-being of member-OFWs and their families;\n(g) To develop, support and finance specific projects for the welfare of member-OFWs and their families; and\n(h) To ensure the implementation of all laws and ratified international conventions within its jurisdiction.\nDEFINITION OF TERMS"}},{"id":"PH-H9249-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Definition of Terms. – As used in this Act:\n(a) Compensation refers to the basic pay or salary received by an officer or employee of the OWWA, pursuant to the official appointment, excluding per diems, bonuses, overtime pay, honoraria, allowances and any other emoluments received that are not integrated into the basic pay under existing laws;\n(b) Contribution or membership fee refers to the amount paid to the OWWA by the employer or by an OFW in accordance with the provisions of this Act;\n(c) Dependent refers to any of the following:\n(1) The legal spouse;\n(2) The legitimate, illegitimate, legitimated, and legally adopted child, who is unmarried, not gainfully employed, and not over the age of majority, or is over the age of majority but incapacitated and incapable of self-support due to a mental or physical defect; and\n(3) The parents who rely primarily upon the member-OFWs for support;\n(d) Non-active OWWA member refers to an OFW whose OWWA membership has expired;\n(e) Non-OWWA member refers to an undocumented OFW and who has not availed of the voluntary membership of the OWWA;\n(f) OWWA member refers to an OFW with a paid contribution or membership fee;\n(g) Overseas Filipino Worker (OFW) refers to a person who is to be engaged, is engaged, or has been engaged in a remunerated activity in a State of which the person is not a citizen, or on board a vessel navigating the foreign seas other than a government ship used for military or noncommercial purposes, or on an installation located offshore or on the high seas; and\n(h) Voluntary OWWA member refers to the OFW who has availed of the voluntary membership of the OWWA at job sites or through electronic registration.\nMEMBERSHIP, CONTRIBUTION AND COLLECTION"}},{"id":"PH-H9249-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Registration of Membership. – Membership in the OWWA may be obtained in two (2) ways:\n(a) By compulsory registration upon processing of employment contracts of OFWs at the POEA; and\n(b) By voluntary registration of OFWs at job sites, or through electronic registration."}},{"id":"PH-H9249-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Amount of Contribution and Effectivity of Membership. – Membership in the OWWA, either through the compulsory or voluntary coverage, shall be effective upon payment of membership contribution in the amount of twenty-five US dollars (US$ 25.00) or its equivalent in the prevailing foreign exchange rates. Such membership shall be considered active until the expiration of the OFWs existing employment contract or after two (2) years from contract effectivity, whichever comes first.\nIn case of voluntary registration, membership shall be considered active until the expiration of the OFWs existing employment contract or after two (2) years from the date of voluntary registration, whichever comes first.\nThe OWWA shall be allowed to collect a subsequent membership contribution from the member-OFW only after every two (2) years from the last membership contribution made."}},{"id":"PH-H9249-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Power of the Board to Adjust the Membership Contribution. – Based on actuarial studies and taking into consideration the welfare and interest of the member-OFWs, the OWWA Board may adjust or modify the amount of membership contribution."}},{"id":"PH-H9249-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Proof of Membership. – Upon payment of the required contribution, an OWWA member shall be issued an official receipt, an OWWA E-Card, identification card, or other proof of membership. No additional or extra charges shall be levied on the member-OFW.\nThe OWWA shall maintain a comprehensive database of member-OFWs, which shall be updated regularly."}},{"id":"PH-H9249-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Separate Accounting of Land-Based and Sea-Based Members’ Contributions. – For a more effective financial management, the membership contributions of land-based and sea-based members shall be accounted for in two (2) separate books of accounts."}},{"id":"PH-H9249-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Authorized Collecting Officers. –\n(a) Membership contributions shall be collected by duly authorized OWWA collecting officers, deputized collecting officers, or accredited collecting agents. The collection of membership contributions shall be made at the POEA contract processing hub, OWWA regional and overseas offices, and other accredited collection centers.\n(b) In case of voluntary members who register at the job site, membership contributions shall be made directly to the OWWA Overseas Offices located in the respective foreign service posts of the Philippines."}},{"id":"PH-H9249-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Reportorial Requirements. – The collecting officer, deputized collecting officer, or the accredited collecting agent shall prepare and submit the required monthly reports to the OWWA Central Office in the Philippines."}},{"id":"PH-H9249-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Handling, Deposit and Remittance of Collection. – The OWWA shall ensure that the handling, deposit and remittance of collections shall be in accordance with the existing rules and regulations of the Commission on Audit (COA), Department of Budget and Management (DBM), and other concerned agencies."}},{"id":"PH-H9249-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Sanctions for Erring Officers. – Corresponding administrative sanctions and other disciplinary measures, including recall from post, suspension, or separation from service, shall be imposed upon any officer who violates Sections 14 and 15 of this Act."}},{"id":"PH-H9249-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Prohibition Against Discrimination on Membership. – No OFW shall be denied membership to the OWWA by reason of age, gender, religious belief, or political affiliation. The OWWA shall take affirmative steps to enhance the access of OFWs to its programs and services."}},{"id":"PH-H9249-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Payment of Contribution or OWWA Fee by Employer. – Contributions to the OWWA Fund must be paid by the employers or principals, or in their default, by the recruitment/manning agency in the case of new hires. The POEA shall ensure that this stipulation is made an integral part of the overseas employment contract."}},{"id":"PH-H9249-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Penalty for Violation by Recruitment/Manning Agency. – Violation by a recruitment/manning agency of the preceding section shall constitute an offense punishable by revocation of its license and all its officers and directors shall be perpetually disqualified from engaging in the business of recruitment/placement of overseas workers. Such penalty is without prejudice to any other liability which the officers and directors may have incurred under existing laws, rules and regulations.\nTHE OWWA BOARD OF TRUSTEES"}},{"id":"PH-H9249-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER V"},"text":{"en":"The OWWA Board of Trustees. – To carry out the purposes of this Act, the OWWA shall be directed and controlled by a Board of Trustees which shall act as its policy-making body. It shall be composed of the following members:\n(a) Secretary of Labor and Employment, as Chairperson;\n(b) OWWA Administrator, as Vice Chairperson;\n(c) Secretary of Foreign Affairs;\n(d) Secretary of Finance;\n(e) Secretary of Budget and Management;\n(f) POEA Administrator;\n(g) Two (2) representatives from the land-based OFWs who are nominated and appointed in accordance with the provisions of Republic Act No. 8042, as amended by Republic Act No. 10022;\n(h) Two (2) representatives from the sea-based. OFWs who are nominated and appointed in accordance with the provisions of Republic Act No. 8042, as amended by Republic Act No. 10022;\n(i) One (1) representative from the women sector who is nominated and appointed in accordance with the provisions of Republic Act No. 8042, as amended by Republic Act No. 10022;\n(j) One (1) representative from the land-based recruitment sector who is selected from among the various associations of registered overseas placement and recruitment agencies based in the Philippines, who shall be appointed by the President of the Philippines to serve a single term of three (3) years; and\n(k) One (1) representative from the sea-based manning sector, who is selected from among the various associations of registered overseas placement and manning agencies based in the Philippines, who shall be appointed by the President of the Philippines to serve a single term of three (3) years.\nThe Trustees holding office as members of the OWWA Board at the time of the effectivity of this Act shall continue to serve until the expiration of their term of appointments.\nIn case of vacancy in any of the appointive positions in the OWWA Board, the vacancy shall be filled by the subsequent nomination of the respective sector concerned, in the same manner as the selection of the predecessor. Such successor shall hold office for the unexpired term."}},{"id":"PH-H9249-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Per Diem. – The members of the OWWA Board shall not receive any compensation but shall be provided with per diem at rates allowed under existing rules and regulations."}},{"id":"PH-H9249-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Responsibilities and Powers of the Board of Trustees. – The Board shall exercise the following specific powers and duties:\n(a) To define the thrusts of the OWWA and adopt policy guidelines to ensure their implementation;\n(b) To preserve the integrity of the OWWA Fund;\n(c) To approve programs, projects, and the organizational structure of the OWWA Secretariat;\n(d) To modify or adjust the membership contribution and other necessary charges based on periodic reviews and actuarial studies, subject to due consultation with OFWs or nongovernment organizations (NGOs) advocating the protection of the rights and welfare of OFWs and their families;\n(e) To formulate rules and regulations governing financial transactions and prepare the annual and supplemental budget of the Secretariat for submission to the DBM;\n(f) To formulate rules and regulations governing the conduct and discipline of OWWA officials and employees in accordance with civil service rules;\n(g) To ensure the efficiency of collection and the viability and sustainability of the fund through sound and judicious investment and fund management policies;\n(h) To receive and appropriate all sums to carry out the purposes and functions of the OWWA;\n(i) To authorize the construction or repair of its buildings, machinery, equipment and other facilities, and the purchase and acquisition of real and personal properties, including the necessary supplies, materials and equipment;\n(j) To receive in trust legacies, gifts and donations of real and personal property of all kinds, and to administer and dispose the same when necessary for the benefit of the OWWA general membership and subject to the instructions of the donor, if any;\n(k) To delegate any of its powers to the Chairperson of the Board or to the Administrator of the OWWA Secretariat in case of any national emergency that affects the rights and welfare of its member-OFWs and their families;\n(l) To prescribe such general policies, rules and regulations, not contrary to law, consistent with the purposes of the OWWA subject to due consultation with OFWs or NGOs advocating the protection of the rights and welfare of OFWs and their families; and\n(m) To exercise such, powers as may be proper and necessary to carry out the objectives of this Act.\nBOARD MEETINGS, PROXIES, AND RECORDS MANAGEMENT"}},{"id":"PH-H9249-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Schedule of Meetings. – The regular meetings of the Board shall be held every last Friday of the month. If a change of date becomes necessary, the meetings shall be held at the most convenient time set by the Board.\nSpecial Board meetings and executive meetings may be scheduled as the need arises. Special Board meetings may be called upon by the Chairperson or upon the instance of five (5) members of the Board."}},{"id":"PH-H9249-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Proceedings of the Board. – The proceedings of the Board shall be governed by the following rules:\n(a) Notice of Meetings – The Board Secretary shall distribute to all members of the Board the notice of meeting, together with the discussion materials, at least three (3) working days prior to the scheduled meeting;\n(b) Quorum – In determining the existence of a quorum, the Board shall adopt the simple majority rule or one-half (1/2) of the total filled Board seats plus one (1);\n(c) Voting – For the approval of any policy requiring the disbursement of at least one hundred million pesos (P100,000,000.00) of the OWWA Fund, an affirmative vote of the absolute majority of all the members shall be required. For the approval of all other policies, an affirmative vote of a majority of the members present constituting a quorum shall be necessary;\n(d) Attendance in Board Meetings – Board members are responsible for attending all Board meetings. The ex officio members of the Board of Trustees may designate in writing their permanent alternate who shall have voting power. The Board shall install teleconferencing facilities in order to muster a quorum during Board meetings;\n(e) Presiding Officer – The Chairperson shall preside over meetings of the Board. In the absence of the Chairperson, the Vice Chairperson shall preside;\n(f) Board Resolution – All decisions of the Board shall be expressed in the form of Resolutions and shall take effect upon adoption and signing by all the members present, subject to requisite publication, as may be required by existing laws, rules and regulations; Provided, That resolutions may be modified or superseded by another resolution; and\n(g) Records Management and Archiving of Board Documents – The Board Secretary shall ensure a complete and thorough recording of all proceedings during a Board meeting. The minutes of the previous meeting shall be made available for approval during the succeeding scheduled Board meeting.\nThe minutes of the meeting shall contain the attendance, business arising from the minutes of the previous meeting, agreements reached, corresponding resolutions, other items noted or discussed, and instructions issued by the Board.\nAll minutes of meetings and Board Resolutions, tape recordings, and other documents pertaining to the business of the Board shall be kept and archived pursuant to standard records management systems, procedures and shall be made accessible to the public at all times.\nOWWA SECRETARIAT"}},{"id":"PH-H9249-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"The OWWA Secretariat. – The OWWA Secretariat shall be the implementing arm of the OWWA."}},{"id":"PH-H9249-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Duties and Responsibilities of the OWWA Secretariat. – The OWWA Secretariat shall perform and assume the following duties and responsibilities:\n(a) To implement all decisions and policies promulgated by the Board including investment and fund management;\n(b) To manage programs and implement the delivery of welfare services to its members, both local and overseas, supported by advocacy and information campaign programs;\n(c) To formulate medium-term development plans responsive to the welfare, needs, and demands of member-OFWs;\n(d) To submit work and financial plans for Board consideration;\n(e) To provide policy analyses and recommendations for Board consideration;\n(f) To conduct continuing research and studies, including impact evaluation, in aid of policy and program development;\n(g) To regularly monitor and conduct assessment and evaluation of organizational performance;\n(h) To establish and maintain an on-line management information system, which shall include a database on membership;\n(i) To establish and maintain linkages and networks with social and institutional partners, both local and international;\n(j) To submit written quarterly reports on the assessment and evaluation of programs, projects and services, and such other reports as maybe required by the Board;\n(k) To conduct an annual planning, budgeting and organizational performance assessment, and render the corresponding report to the Board;\n(l) To submit annual reports to the Board, the Congress and the President of the Philippines;\n(m) To undertake a periodic review of programs, standards, thrusts, and policies;\n(n) To perform other functions as may be instructed by the Board; and\n(o) To adopt internal rules of procedure consistent with the provisions of this Act."}},{"id":"PH-H9249-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"The OWWA Administrator. – The management and supervision of the OWWA shall be vested in the Administrator. As the Chief Executive Officer of the Secretariat, the Administrator shall oversee the overall operations of the Secretariat, which shall include the general supervision and control of all its personnel and resources, and the assumption of full responsibility and accountability thereof.\nThe Administrator must possess good leadership and managerial skills, and shall be appointed by the President of the Philippines. The Administrator shall report to the President, through the Secretary of the DOLE, and shall perform the duties and functions stated in this Act and all the necessary and related functions of the office of the Administrator, subject to the policies and rules prescribed by the OWWA Board."}},{"id":"PH-H9249-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"The Deputy Administrators. – Two (2) Deputy Administrators shall assist the Administrator in the management and supervision of operations of the OWWA. There shall be one (1) Deputy Administrator for Administration and Fund Management, and one (1) Deputy Administrator for Operations. They shall also be appointed by the President upon the recommendation of the Administrator. They must also possess good leadership and managerial skills. The Board may assign specific functional responsibilities to the Deputy Administrators."}},{"id":"PH-H9249-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Regional and On-site Welfare Offices. – The OWWA shall maintain Regional and On-site Welfare Offices under the Philippine Overseas Labor Offices (POLOs) of the DOLE.\nPERSONNEL AND STAFFING PATTERN"}},{"id":"PH-H9249-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Authority of the Board to Reorganize the Administration. – Notwithstanding the provisions of existing laws, the OWWA Board shall conduct a management audit within one hundred twenty (120) days from the effectivity of this Act and submit to the DBM a proposed reorganization plan of the OWWA not later than one (1) year after the audit, subject to the limitations provided under this Act and based on the following criteria:\n(a) Increased OWWA visibility from the head office to the various regional offices, and by the appointment and assignment of personnel to positions that are purely administrative, technical, clerical in nature, and other positions that are not actually and directly related to its operation and administration; and\n(b) Efficient and optimized delivery of OWWA services to the OFWs and their respective families. The OWWA shall ‘endeavor to assign its representatives in every foreign post of the Philippines to, among others, ensure the provision of services to member-OFWs and the promotion of voluntary membership to non-members."}},{"id":"PH-H9249-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Qualifications Upgrading Program. – The OWWA Board shall design and establish a qualifications upgrading program for the staffing of the OWWA, in coordination with the DOLE and the Civil Service Commission (CSC), within one hundred twenty (120) days from the effectivity of this Act: Provided, That those who are already in the service from the effectivity of this Act shall have, not later than five (5) years, obtained the required academic degree and/or qualifications counted from the implementation of the qualifications upgrading program: Provided, further, That those who are already in the service from the effectivity of this Act shall have, not later than one (1) year, obtained the necessary CSC qualification required for the position they are currently holding: Provided, finally, That said personnel have obtained at least a satisfactory performance rating."}},{"id":"PH-H9249-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"New Structure and Staffing Pattern. –\n(a) The new structure and staffing pattern for the OWWA shall be prescribed by the OWWA Board and shall be submitted to the Secretary of the DBM for approval. The salaries and benefits of all personnel shall be in accordance with existing compensation laws.\n(b) The current officials and employees of the OWWA, as organized under Letter of Instruction No. 537 and Presidential Decree No. 1694, as amended by Presidential Decree No. 1809, and renamed under Executive Order No. 126, series of 1987, and OWWA Board Resolution No. 001, series of 2004, shall be appointed, reappointed, or transferred to the appropriate unit in the new OWWA organizational structure, as determined by the Board, and subject to the qualifications provided in Section 31 of this Act. There shall be no gender discrimination, no demotion in ranks and positions and no diminution in salaries, benefits, allowances and emoluments of all OWWA personnel."}},{"id":"PH-H9249-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"General Qualifications for Appointment. – The general qualifications for appointment of OWN A personnel shall be in accordance with the minimum qualification standards requirements set by the CSC. The OWWA may hire experts in actuarial studies, information technology, finance and investment, and such other fields as may be deemed necessary in the implementation of its programs and services.\nOWWA BENEFITS AND SERVICES"}},{"id":"PH-H9249-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Guiding Principles. – Pursuant to its mandate, the OWWA shall provide gender-responsive reintegration programs, repatriation assistance, loan and credit assistance, on-site workers assistance, death and disability benefits, health care benefits, education and skills training, social services, family welfare assistance, programs and services for women migrant workers and other appropriate programs that provide timely social and economic services.\nNothing in this Act shall be construed as a limitation or denial of the right of an OFW to avail of any benefit plan which may be adopted in the employment contract, or offered voluntarily by employers, or by the laws of the receiving country, over and above those provided under this Act."}},{"id":"PH-H9249-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Benefits and Services to OFWs. –\n(a) Reintegration of OFWs. – The reintegration of OFWs, taking into consideration the needs of women migrant workers, shall be one of the core programs of the OWWA. In this regard, and for purposes of policy and program coordination, the National Reintegration Center for OFWs created under Republic Act No. 10022 shall be an attached office of the OWWA. It shall be headed by an Executive Director who shall be under the supervision of the OWWA Administrator.\nTo be able to sustain the viability of this program, not less than ten percent (10%) of OWWA’s collection of contribution for the immediately preceding year shall be allocated annually for the reintegration program,\n(b) Repatriation Assistance. – Consistent with the provisions of Republic Act No. 8042, as amended, the OWWA shall assist the Department of Foreign Affairs in providing OFWs with services necessary to facilitate repatriation, as may be required.\n(c) Loan and Other Credit Assistance. – The OWWA shall provide low-interest loans to member-OFWs. It shall have the authority to hire experts in finance or banking to assist in implementing the said loan programs.\n(d) Workers Assistance and On-site Services. – The OWWA shall sustain and maintain assistance to member-OFWs in all its overseas and regional offices. Services shall be gender-responsive and shall include information regarding the names, occupation/job categories and addresses of the member-OFWs; legal assistance providing guidance and information on protection of migrant rights, including the prevention of gender-based violence; developing materials for the predeparture orientation seminars; conducting psycho-social counseling services; conciliation services; appropriate services and intervention for victims of gender-based violence, and outreach missions, among others. The OWWA shall likewise make competent representations with employers, agents, and host government authorities to assist member-OFWs in obtaining relief from grievances and work-related issues, including claims for unpaid wages, and illegal recruitment cases among others.\n(e) Social Benefits. – A member-OFW shall be covered with the following social benefits:\n(1) Death and Disability Benefits:\n(i) Death Benefits. – A member shall be covered with life insurance for the duration of his or her employment contract. The coverage shall include one hundred thousand pesos (P100,000.00) for natural death and two hundred thousand pesos (P200,000.00) for accidental death;\n(ii) Disability and Dismemberment Benefits. – Disability and dismemberment benefits shall be included in a member’s life insurance policy, as provided for in the impediment schedule contained in the OWWA Manual of Systems and Procedures. The coverage is within the range of two thousand pesos (P2,000.00) to fifty thousand pesos (P50,000.00);\n(iii) Total Disability Benefit. – In case of total permanent disability, a member shall be entitled to one hundred thousand pesos (P100,000.00); and\n(iv) Burial Benefit. – A burial benefit of twenty thousand pesos (P20,000.00) shall be provided in case of the member’s death.\nBased on actuarial studies, the Board may increase the amount of the abovementioned benefits.\n(2) Health Care Benefits. – Within two (2) years from the effectivity of this Act, the OWWA shall develop and implement health care programs for the benefit of member-OFWs and their families, taking into consideration the health care needs of women as provided for in Republic Act No. 9710, or the Magna Carta of Women, and other relevant laws.\n(3) Education and Training Benefits. – A member, or the member’s designated beneficiary, may avail any of the following scholarship programs, subject to a selection process and accreditation of participating institutions:\n(i) Skills-for-Employment Scholarship Program. – For technical or vocational training scholarship;\n(ii) Education for Development Scholarship Program. – For baccalaureate programs; and\n(iii) Seafarers’ Upgrading Program. – To ensure the competitive advantage of Filipino seafarers in meeting competency standards, as required by the International Maritime Organization (IMO), International Labor Organization (ILO) conventions, treaties and agreements, sea-based members shall be entitled to one upgrading program for every three (3) membership contributions.\nThe annual scholarship lists of all these programs shall be submitted to the Board."}},{"id":"PH-H9249-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"New Programs, Interactive Website and Extension of Services. – The OWWA shall continue to develop and implement new programs to meet new OFW needs and requirements as they arise, and to assess the effectiveness of existing services and benefits in serving the welfare of OFWs.\nThe OWWA shall also maintain an interactive website to collect OFW feedbacks, comments, suggestions, and complaints on existing programs and services.\nThe OWWA may also extend appropriate programs or services to non-members, as may be determined by the Board.\nTHE OWWA TRUST FUND"}},{"id":"PH-H9249-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"CHAPTER X"},"text":{"en":"The OWWA Fund. – The Welfare Fund for Overseas Workers created under Letter of Instruction No. 537 and Presidential Decree No. 1694, as amended by Presidential Decree No. 1809, is hereinafter referred to as the OWWA Fund. The OWWA Fund is a private fund held in trust by the OWWA. Being a trust fund, no portion thereof or any of its income, dividends or earnings shall accrue to the general fund of the National Government. Neither shall any amount or portion thereof be conjoined with government money, nor revert to the National Government. In the same manner, it is exempted from the “one fund doctrine” of the government."}},{"id":"PH-H9249-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Purpose of the OWWA Fund. – The OWWA Fund can only be used for the purposes for which it was created, that is, to serve the welfare of member-OFWs and their families which shall include the financing of core programs and services of the OWWA.\nNo funds shall be withdrawn from the OWWA Fund to respond, aid, supplement, or in any manner augment any required expenditure by other government agencies."}},{"id":"PH-H9249-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Source of the OWWA Fund. – The OWWA Fund is the sum total of the amounts under the management and fiscal administration of the OWWA Board and the Secretariat, including the twenty-five US dollars (US$25.00) contributions that shall accrue to the Fund as fees, investment and interest income, and income from other sources."}},{"id":"PH-H9249-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Disbursement of the OWWA Fund. – Any provision of existing law to the contrary notwithstanding, all incomes generated by the OWWA shall, upon their collection, be retained by the OWWA and disbursed at the discretion of the Board for providing services and other benefits of the OWWA general membership and their families."}},{"id":"PH-H9249-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Trustees of the Fund. – The Board is designated as the trustee of the OWWA Fund. It is bound by a fiduciary duty to manage the Fund with extraordinary diligence and with utmost skill, care and judiciousness."}},{"id":"PH-H9249-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Transparency. – The OWWA Fund shall be managed with full transparency and full public disclosure. The OWWA shall make available all records of how the funds are utilized, disbursed, and invested, in accordance with existing laws."}},{"id":"PH-H9249-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Reporting of the OWWA Fund Collection and Utilization. – Within fifteen (15) days after receipt of audited reports from the COA, the OWWA Board of Trustees shall submit to the Congress and the President of the Philippines a report showing the total collections of, and the disbursements from, the OWWA Fund and shall publish the electronic copy of the report and make them available online, in a format that is searchable, accessible and useful to the public.\nINVESTMENT ADMINISTRATION: SAFEGUARDS"}},{"id":"PH-H9249-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Safeguards of the OWWA Fund; Acquired Assets; Unredeemed Investments. –\n(a) The OWWA Fund shall be managed and expended in accordance with the purposes stipulated in this Act and safeguarded against any possible loss and misuse.\nThe OWWA shall ensure an appropriate growth rate in the Fund sufficient to sustain the growing needs of member-OFWs. It shall periodically conduct an inventory of its investment instruments and ensure that they are properly kept at a government bank under a custodianship agreement.\nA monthly report on all investment schedules showing the interest rates, yields, discount rates, and other relevant data, shall be submitted to the Board.\n(b) The OWWA shall administer all properties, acquired or foreclosed.\nTo ensure that the properties are safeguarded and preserved, the same must be properly accounted for and documented, reinspected, reappraised, and insured.\nAn asset development/disposal plan shall be submitted by the Administrator for the consideration of the Board.\nForeclosed properties shall be registered as OWWA assets within one (1) month after foreclosure.\n(c) Unredeemed investments and other receivables shall be inventoried semi-annually and corresponding redemption plan shall be submitted to tide Board. All receivables shall be supported by documents appropriately acknowledged by the accountable party."}},{"id":"PH-H9249-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"General Investment Policy. – Upon approval of the Board, all OWWA investments shall be placed only in government securities and bonds which provide optimum earnings, liquidity and protection of the Fund. Portfolio management of investible funds shall be outsourced to GFIs."}},{"id":"PH-H9249-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Examination and Valuation of the Funds. – The OWWA shall make a periodic actuarial examination and valuation of its funds in accordance with accepted actuarial principles.\nFISCAL AND BUDGET POLICY: MANAGEMENT OF OWWA FUND"}},{"id":"PH-H9249-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Budget for Benefits and Services. – The annual budget for benefits and services to OWWA members and their families shall be sourced from the OWWA funds."}},{"id":"PH-H9249-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Budget Preparation and Approval. – In preparing the annual budget for benefits and services, the OWWA shall follow the national government budget system, format and cycle.\nThe Board shall approve the annual budget, by a majority vote of all its members."}},{"id":"PH-H9249-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Reenacted Budget. – In case the proposed annual budget sourced from the OWWA Fund has not been approved by the Boar d at the start of the year, the OWWA shall operate within the budget level of the previous year allocated on a month-to-month basis. All savings realized in the previous year shall be deducted from the current year’s budget."}},{"id":"PH-H9249-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Budget Realignment. – Realignment of funds sourced from the OWWA Fund including adjustments in targets shall be submitted to the Board for approval. Similarly, in the event that extraordinary circumstances may occur which require sourcing of additional funds from the OWWA Fund beyond the coverage of the approved budget, the same shall be submitted to the Board for approval."}},{"id":"PH-H9249-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Branch Accounting System; Financial Reports; Auditing Procedures; Annual Reports. – The OWWA Regional Units shall maintain their respective books of accounts which shall be consolidated by the central office.\nThe OWWA shall install sound internal control and monitoring systems and submit quarterly prescribed Financial Statements to the COA, such as income statement, balance sheet, and cash flow as prescribed in post auditing reports by the COA.\nThe OWWA Secretariat shall submit a monthly fund utilization report to the Board, copies of which shall be made available to Congress. It shall also submit an Annual Report on its overall performance for the previous year within the first sixty ‘ (60) days of the following year to the OWWA Board, the Congress and the President of the Philippines, through the DBM."}},{"id":"PH-H9249-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Chart of Accounts. – The OWWA shall adopt the appropriate and standard chart of accounts as prescribed by the COA APPROPRIATION FROM THE NATIONAL GOVERNMENT"}},{"id":"PH-H9249-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Appropriation from the National Government. – The amount needed to carry out the initial implementation of this Act shall be charged against the current operative budget sourced from the internal funds of the OWWA. Thereafter, such lump sum representing the responsibility of the National Government for the continued operations and maintenance of the OWWA shall be included in the annual General Appropriations Act (GAA).\nCongress shall annually appropriate the necessary amount to meet the funding requirement for personal services (PS) and the maintenance and other operating expenses (MOOE) of the OWWA. Nothing in this Act shall prevent the National Government from allocating funds for the operation or implementation of any of the programs or services stated herein, including the budget for capital outlay (CO).\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H9249-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Rebates for Long-time Members. – In recognition of the contribution of long-time members to the OWWA Fund, the OWWA shall develop and implement a program for the grant of rebates or some form of financial assistance to OFWs who have been members of the OWWA for at least ten (10) years and who, along with their families, have not availed of any service or benefit from the OWWA. The provision and the amount of rebates shall be based on actuarial study commissioned by the OWWA for this purpose."}},{"id":"PH-H9249-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Procurement System. – The OWWA procurement system shall be governed by Republic Act No. 9184, also known as the “Government Procurement Reform Act”."}},{"id":"PH-H9249-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Exemption from Tax, Legal Process and Lien. – All laws to the contrary notwithstanding, the OWWA and all its assets and properties, all contributions collected and all accruals thereto and income or investment earnings therefrom as well as all supplies, equipment, papers or documents shall be exempt from any tax, assessment, fee, charge, or customs or import duty. All benefit payments made by the OWWA shall likewise be exempt from all kinds of taxes, fees or charges, and shall not be liable to attachments, garnishments, levy or seizure by or under any legal or equitable process, either before or after receipt by the person or persons entitled thereto, except to pay any debt of the member to the OWWA. No tax measure of whatever nature enacted shall apply to the OWWA, unless this section is expressly, specifically and categorically revoked or repealed by law and a provision is enacted to substitute or replace the exemption referred to herein. Any tax assessment imposed against the OWWA shall be null and void."}},{"id":"PH-H9249-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Transitory Provision. – All facilities, equipment, supplies, records, files, appropriations and funds under the OWWA, as organized under Letter of Instruction No. 537 and Presidential Decree No. 1694, as amended by Presidential Decree No. 1809, and renamed under Executive Order No. 126, series of 1987, shall remain with the OWWA.\nCurrent officials and employees of the OWWA shall continue to draw their salaries, benefits and emoluments from the OWWA Fund until such time, but not later than one (1) year from the effectivity of this Act, that the corresponding funds from the National Government shall have been appropriated and released to the OWWA."}},{"id":"PH-H9249-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Implementing Rules and Regulations. – Within ninety (90) days from the effectivity of this Act, the present OWWA Board shall promulgate the rules and regulations implementing the provisions of this Act. The implementing rules and regulations issued pursuant to this section shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}},{"id":"PH-H9249-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Separability Clause. – If any provision of this Act is declared unconstitutional, the remainder of this Act or any provision not affected thereby shall remain in full force and effect."}},{"id":"PH-H9249-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Repealing Clause. – Letter of Instruction No. 537, Presidential Decree No. 1694 and Presidential Decree No. 1809 are hereby repealed. All other laws, decrees, executive orders, rules and regulations inconsistent with the provisions of this Act are likewise repealed."}},{"id":"PH-H9249-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Governing the Operations and Administration of the Overseas Workers Welfare Administration","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9250"] = {"id":"PH-H9250","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10802_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布每年7月4日为南拉瑙省特别工作假日及学校停课日，以纪念其建省纪念日的法案","en":"An Act Declaring July 4 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of Lanao Del Sur in Commemoration of Its Foundation Day","orig":"An Act Declaring July 4 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of Lanao Del Sur in Commemoration of Its Foundation Day"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10802","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10802_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9250-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July 4 of every year is hereby declared a special working holiday and no class day in schools in the Province of Lanao del Sure in commemoration ot its foundation day."}},{"id":"PH-H9250-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee is entitled to his/her regular wage."}},{"id":"PH-H9250-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Declaring July 4 of Every Year a Special Working Holiday and No Class Day in Schools in the Province of Lanao Del Sur in Commemoration of Its Foundation Day","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H9251"] = {"id":"PH-H9251","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2016/ra_10803_2016.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Imus市","en":"An Act Declaring June 30 of Every Year a Special Working Holiday and No Class Day in Schools in the City of Imus, Province of Cavite in Commemoration of Its Founding Anniversary","orig":"An Act Declaring June 30 of Every Year a Special Working Holiday and No Class Day in Schools in the City of Imus, Province of Cavite in Commemoration of Its Founding Anniversary"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 10803","issuingBody":"Congress of the Philippines","promulgatedDate":"2016-05-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2016/ra_10803_2016.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9251-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"June 30 of every year is hereby declared a special working holiday and no class day in schools in the City of Imus, Province of Cavite in a commemoration of its founding anniversary."}},{"id":"PH-H9251-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For work performed on a special working holiday, an employee is entitled to his/her regular wage."}},{"id":"PH-H9251-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p131"};
